  insert into public.blog_articles (id,title,slug,excerpt,category_id,author_id,status,featured_image_path,featured_image_alt,featured_image_caption,seo_title,seo_description,social_image_path,canonical_url,indexing_enabled,recommended,legacy_migrated,published_at,scheduled_at,archived_at)
  insert into public.blog_articles (id,title,slug,excerpt,category_id,author_id,status,featured_image_path,featured_image_alt,featured_image_caption,seo_title,seo_description,social_image_path,canonical_url,indexing_enabled,recommended,legacy_migrated,published_at,scheduled_at,archived_at)
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('18a39a98-91c1-448e-9525-058878460e34','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',1,'{"text":"Možná už sis několikrát řekla, že tentokrát začneš cvičit pravidelně. První den se odhodláš, připravíš si podložku a pustíš se do tréninku. Jenže potom přijde náročný den v práci, únava, nemocné dítě nebo víkend plný povinností. Jeden trénink vynecháš, potom druhý a za pár dní máš pocit, že celý pokus zase skončil."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('aa462584-17d7-4a05-b539-2aa54f8900da','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',2,'{"text":"Neznamená to, že nemáš dost pevnou vůli. Často sis jen vybrala plán, který vypadal dobře na papíře, ale nevešel se do tvého skutečného života."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ae51be6a-cfad-4be2-833f-6eaf5a5e008b','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',3,'{"level":"h2","text":"Proč většina pokusů skončí dřív, než se z pohybu stane zvyk","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('289295b9-6436-446c-91f6-e20954ad1f3f','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',4,'{"text":"Když se rozhodneš začít, je lákavé nastavit si velký cíl. Dlouhé tréninky několikrát týdně, rychlé výsledky a pocit, že tentokrát do toho musíš dát všechno. Takový plán ale funguje hlavně ve dnech, kdy máš dost času, energie a motivace."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7bc74768-f24a-4d8a-ab8c-6b91392602bd','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',5,'{"text":"Jakmile přijde obyčejný náročný den, začne se rozpadat. Pokud má cvičení trvat hodinu, musíš tu hodinu nejdřív někde najít. Když ale víš, že tě čeká krátký pohyb, je mnohem snazší opravdu začít. Pokud si chceš nejdřív ujasnit úplné základy, přečti si také [jak začít cvičit, když nemáš čas](/blog/jak-zacit-cvicit-kdyz-nemas-cas)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e260c3d8-89c7-4752-a1b4-dd72fd949be8','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',6,'{"level":"h2","text":"Nepotřebuješ perfektní výkon. Potřebuješ zvládnutelný začátek","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1f768204-40eb-4358-8eed-a98640512b1f','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',7,'{"text":"Nemusíš po prvním tréninku odcházet úplně vyčerpaná. Nemusíš se druhý den probudit s bolestí celého těla. A cvičení nemusí trvat hodinu, aby mělo smysl."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fb719225-f3e8-4549-a123-f8d95ad1bb9e','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',8,'{"text":"Mnohem důležitější je získat zkušenost, že pohyb zvládneš zařadit i do normálního dne. Krátký trénink, který opravdu odcvičíš, ti dá víc než dokonalý plán, který zůstane uložený v telefonu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('968eb38e-d3fa-4e04-a38c-9a64245239a2','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',9,'{"level":"h2","text":"Jak začít, aby ti pohyb tentokrát vydržel","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d0c7f0a0-eb99-4e36-afc9-e0abc1ea9e2a','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',10,'{"level":"h3","text":"1. Zmenši první krok","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ea3eb1b5-ac61-49cd-9204-b0ae75fe428e','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',11,'{"text":"Nezačínej otázkou, kolikrát týdně bys ideálně měla cvičit. Zeptej se sama sebe: Jak dlouhý pohyb zvládnu i ve dni, kdy se mi nebude chtít? Může to být deset minut. Někdy jen pět. Cílem není udělat maximum. Cílem je začít tak, aby sis mohla říct: Tohle zvládnu znovu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('35a8895b-38b3-41ad-a9d3-bba148d75503','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',12,'{"level":"h3","text":"2. Měj připravený konkrétní plán","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1a4cc13b-2993-46a8-9e24-8ed4378087d7','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',13,'{"text":"Rozhodování bere energii. Když musíš pokaždé hledat vhodné video, přemýšlet, co budeš cvičit, a zjišťovat, jestli je trénink pro tebe, vzniká další důvod pohyb odložit. Pomůže ti, když přesně víš, co tě čeká, jak dlouho to potrvá a co máš udělat další den."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('96d4b032-5606-4f03-b938-92b2b16c6bb7','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',14,'{"level":"h3","text":"3. Nečekej na chuť","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7f04cade-d6c4-43b4-8af5-a8e452a4a739','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',15,'{"text":"Chuť ke cvičení často nepřijde před pohybem. Přijde až během něj nebo po něm. Proto si neříkej, že musíš odcvičit celý trénink. Řekni si pouze, že začneš. Převlékni se, připrav si místo a pusť první minutu. Nejtěžší bývá právě začátek."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('34ad607d-4b7b-4902-a6aa-559dc81b7a01','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',16,'{"level":"h3","text":"4. Počítej i s horšími dny","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a174cbde-9397-4895-b0e5-dc093091d88a','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',17,'{"text":"Dobrý plán není ten, který funguje pouze tehdy, když jde všechno podle představ. Dobrý plán počítá s únavou, nedostatkem času i dnem, kdy se ti nechce. V takovou chvíli nemusíš nic dohánět. Udělej kratší variantu a pokračuj dál."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b55fcea7-8dd6-4a90-840b-9f9e68030395','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',18,'{"level":"h2","text":"Co se může změnit za 21 dní","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a557e803-279f-4d68-933a-640e23d0e179','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',19,'{"text":"Za tři týdny nemusíš získat vysněnou postavu ani perfektní kondici. Můžeš ale získat něco mnohem důležitějšího pro další pokračování:"}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fec56c81-d010-4a68-99ff-2dd5fc139890','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','bullet_list',20,'{"items":["přestaneš mít pocit, že je cvičení příliš náročné","vyzkoušíš si krátké domácí tréninky","začneš lépe vnímat své tělo","zjistíš, že pohyb zvládneš i bez fitness centra","vytvoříš si první jednoduchý návyk","nebudeš každý den řešit, co máš cvičit"]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f1ab27d2-9b0e-4352-a632-bcf2b3cbc33f','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','heading',21,'{"level":"h2","text":"21denní výzva Fit bez času ti dá jasný první krok","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('777ee223-c7a6-44df-8c27-778e09a87cd4','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',22,'{"text":"Výzva je vytvořená pro ženy, které se chtějí začít pravidelně hýbat, ale nechtějí svůj den podřídit složitému tréninkovému plánu. Čekají tě krátká domácí cvičení bez návštěvy fitness centra a bez zbytečného vybavení."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a8808fff-30dc-4e34-9c5f-bf85821bd889','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','paragraph',23,'{"text":"Každý den budeš vědět, co máš udělat. Nemusíš hledat vhodný trénink, skládat si vlastní plán ani čekat, až budeš mít více času. Nemusíš být ve formě a nemusíš mít zkušenosti. Stačí začít prvním dnem."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7f4c34e7-e964-4891-a3b5-09bc6f13b6d3','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','cta',24,'{"eyebrow":"21denní výzva","title":"Chceš začít s pohybem bez dalšího přepálení?","text":"Ve 21denní výzvě dostaneš krátká domácí cvičení a jasnou strukturu, která počítá i s běžnými náročnými dny.","button_label":"Prohlédnout 21denní výzvu","url":"https://www.fitbezcasu.cz/21dennivyzva","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1ba9cdb2-6a78-4093-b92c-03155728d64c','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',1,'{"text":"Chceš začít hubnout, ale při představě jídelníčku, pravidelného cvičení a kompletní změny režimu už dopředu cítíš, že to vedle práce a rodiny nezvládneš?"}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('83c261e4-a974-48ed-b8a0-50466d51008e','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',2,'{"text":"Možná už jsi několikrát začala. První dny ses snažila dělat všechno správně, jenže potom přišel náročný týden, vynechané cvičení a pocit, že jsi zase selhala. Nejspíš ti ale nechybí větší disciplína. Potřebuješ začátek, který počítá s tím, jak tvůj den skutečně vypadá."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('12c3fb48-253c-4c62-b093-5ca5637b53ad','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',3,'{"text":"Hubnutí pro začátečníky nemá začínat maximálním výkonem. Má začít krokem, který dokážeš zopakovat i zítra."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('73058157-2b34-45c1-8a80-aa85345e0d8c','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',4,'{"level":"h2","text":"Proč je tak těžké začít hubnout","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a4200969-c011-4d41-ba7b-5838bfea51d0','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',5,'{"text":"Když se rozhodneš něco změnit, chceš obvykle vidět výsledek co nejrychleji. Proto si nastavíš více cvičení, přísnější jídlo a dlouhý seznam věcí, které odteď nesmíš dělat. Tento plán může několik dní fungovat. Jenže je postavený na nadšení, ne na běžném životě."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c6426667-0321-49b9-80bd-674d82a79994','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',6,'{"text":"Jakmile motivace zeslábne, zůstane ti režim, který vyžaduje příliš mnoho času a rozhodování. Pak stačí jeden hektický den a celý plán se začne rozpadat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b53e9187-b64d-4b30-8449-aad2dfa96cd9','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',7,'{"level":"h2","text":"Co ženy při prvním pokusu často přepálí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fe67068a-61f0-4921-ab39-dcb527f04d1c','7d4dc0ef-aee6-49c6-961e-ae10ed901169','bullet_list',8,'{"items":["Začnou tréninkem, který je na jejich současnou kondici příliš náročný.","Naplánují si pohyb pětkrát týdně, přestože dosud necvičily vůbec.","Počítají jen s ideálním dnem a nemají kratší variantu pro dny, kdy nestíhají.","Hodnotí úspěch podle spálených kalorií místo podle vytvořeného návyku.","Po jednom vynechání mají pocit, že musí začít znovu od nuly."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('12df6455-1f63-4152-955c-0a04178c3fe0','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',9,'{"level":"h2","text":"Jak začít hubnout, když nemáš čas","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('0da69f66-d7e9-49b8-9478-147937bfc039','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',10,'{"level":"h3","text":"1. Odděl začátek od výsledku","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('507d5249-d101-474f-a4bc-d5b26cd9c212','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',11,'{"text":"Nemusíš si hned představovat, kolik kilogramů chceš shodit. Pro první tři týdny si stanov jednodušší výsledek: chci se pravidelně hýbat a zjistit, že pohyb dokážu vměstnat i do normálního dne."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1d7dc948-00f3-46b8-963e-ffeca89fcbcc','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',12,'{"level":"h3","text":"2. Zmenši cvičení tak, aby nešlo snadno odmítnout","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('747bb5c2-0d59-4d44-9cdd-4b49cb7ae7a6','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',13,'{"text":"Deset minut cvičení denně může na papíře vypadat málo. Pro vytvoření návyku je ale krátké cvičení často mnohem cennější než hodinový trénink, ke kterému se dostaneš jednou za deset dní."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a86ca9ff-f3b8-4fb5-bbfc-68649fb29ece','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',14,'{"text":"Krátké cvičení na hubnutí doma nevyžaduje cestu do fitness centra, hlídání dětí ani složitou přípravu. Můžeš začít v obýváku a po několika minutách se vrátit k běžnému dni. S pravidelností ti může pomoct také návod, [jak si vytvořit návyk cvičení](/blog/jak-si-vytvorit-navyk-cviceni)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('997700bc-60c4-448a-8b54-93e3bc6bde20','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',15,'{"level":"h3","text":"3. Rozhodni předem, kdy budeš cvičit","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9871a814-55c6-486a-a546-cb25389c0178','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',16,'{"text":"„Až budu mít čas“ není konkrétní plán. Urči si okamžik, který se v týdnu opakuje. Může to být po ranní kávě, po příchodu z práce nebo před večerní sprchou. Když pohyb spojíš s existujícím bodem dne, nemusíš pokaždé znovu rozhodovat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e235f404-6cc3-45f5-a601-1e866175ed1c','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',17,'{"level":"h3","text":"4. Připrav si i minimální variantu","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2b61505e-fea4-43c7-b755-000abd421ad2','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',18,'{"text":"Některé dny zvládneš celý trénink. Jindy budeš unavená nebo tě bude tlačit čas. V takové chvíli nepotřebuješ plán zahodit. Potřebuješ vědět, co je tvoje minimum. Třeba pět minut protažení nebo první část připraveného cvičení."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('eb76ec7d-4d03-4724-aa60-e8c6e2e028dd','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',19,'{"level":"h3","text":"5. Nečekej, až se ti bude chtít","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('561bf247-0eae-4c91-a516-dc5c7c2c71ce','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',20,'{"text":"Motivace často přichází až po začátku. Řekni si, že uděláš první dvě minuty. Jakmile se převlékneš a začneš, pokračování bývá jednodušší. A pokud po dvou minutách opravdu nemůžeš, i tak jsi udržela kontakt s návykem."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('840bcf20-d37c-49d9-8d71-c4c9cde4ac34','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',21,'{"level":"h2","text":"Co můžeš čekat od prvních 21 dní","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5d61f8da-b9b6-4a88-946b-6b2b60f06dec','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',22,'{"text":"Tři týdny nejsou kouzelná hranice, po které už nikdy nebudeš bojovat s nechutí. Jsou ale dost dlouhé na to, abys zažila různé typy dnů a naučila se pokračovat i tehdy, když není všechno ideální."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('aab1ca07-3877-4c48-8699-dd44fbb10cb2','7d4dc0ef-aee6-49c6-961e-ae10ed901169','bullet_list',23,'{"items":["Vyzkoušíš si, kam pohyb nejlépe zapadá do tvého dne.","Zjistíš, jaké tempo a druh cvičení ti vyhovuje.","Přestaneš před každým tréninkem hledat nové video.","Začneš vnímat pohyb jako zvládnutelnou součást dne, ne jako velkou akci.","Získáš první důkaz, že nemusíš čekat na více času."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ac4a5463-e417-4009-b82a-a1e41884b2e6','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',24,'{"level":"h2","text":"Proč samotné „budu se více hýbat“ nestačí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a28b5aa9-5a50-4355-be0f-650b7b4788e1','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',25,'{"text":"Obecný cíl ti neříká, co máš udělat dnes. Právě proto může být výzva na hubnutí pro začátek užitečnější než další seznam rad. Každý den máš před sebou konkrétní úkol a nemusíš řešit, zda sis vybrala správný trénink."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('609c843a-5894-4977-9fca-e68ddbfe9893','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',26,'{"text":"Dobrá 21denní výzva zároveň nemá být trest ani test kondice. Má tě provést začátkem tak, aby ses nepřetížila a získala chuť pokračovat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ff4afaa5-dac7-464f-b0e8-439d1997473e','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',27,'{"level":"h2","text":"Pro koho je 21denní výzva Fit bez času","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('00fe4e4e-af72-45e0-be8c-d110fc31baee','7d4dc0ef-aee6-49c6-961e-ae10ed901169','bullet_list',28,'{"items":["Dlouho jsi necvičila a nevíš, jak bezpečně začít.","Chceš cvičení na hubnutí doma bez složitého vybavení.","Máš nabitý den a potřebuješ krátké tréninky.","Opakovaně začínáš příliš rychle a potom přestaneš.","Nechceš každý den hledat, co máš cvičit."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3ba58b34-7267-4b1d-888b-2e246ac1fce1','7d4dc0ef-aee6-49c6-961e-ae10ed901169','heading',29,'{"level":"h2","text":"Co přesně ti výzva usnadní","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f9213e51-2c46-4bc6-85fb-2d1743d9b6bd','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',30,'{"text":"V 21denní výzvě Fit bez času dostaneš připravený plán krátkého domácího pohybu. Nemusíš sestavovat tréninky, přemýšlet nad pořadím ani čekat, až se objeví ideální hodina volna."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('15982786-b719-4ac3-82db-e98322086d26','7d4dc0ef-aee6-49c6-961e-ae10ed901169','paragraph',31,'{"text":"Výzva je vstupní krok pro ženu, která chce začít, ale nechce svůj život okamžitě podřídit náročnému programu. Neprodává představu, že za tři týdny vyřešíš všechno. Dává ti něco důležitějšího: jasný začátek, který můžeš opravdu dokončit."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6cd29c38-190e-44f5-9333-f36da4c365c6','7d4dc0ef-aee6-49c6-961e-ae10ed901169','cta',32,'{"eyebrow":"21denní výzva","title":"Chceš začít s pohybem bez dalšího přepálení?","text":"Ve 21denní výzvě dostaneš krátká domácí cvičení a jasnou strukturu, která počítá i s běžnými náročnými dny.","button_label":"Prohlédnout 21denní výzvu","url":"https://www.fitbezcasu.cz/21dennivyzva","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c91d1824-691b-4760-b23c-4c5dc1627797','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',1,'{"text":"Na internetu najdeš stovky jídelníčků na hubnutí. Některé slibují rychlé výsledky, jiné obsahují přesně rozepsanou snídani, oběd i večeři. Problém je, že většina z nich neví nic o tobě."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6a7b4487-90ca-44bc-bbf9-ae4f60994f0a','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',2,'{"text":"Neví, kolik energie potřebuješ, kdy pracuješ, kolik času máš na vaření, co jí tvoje rodina ani v kterou část dne tě nejčastěji přepadne hlad. Proto může ukázkový jídelníček vypadat dobře, ale v praxi se rozpadnout během několika dnů."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8b1ff8d0-87a2-4cb5-8e85-e76d19b0a542','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',3,'{"text":"Funkční jídelníček na hubnutí není jen seznam zdravých receptů. Je to systém, který ti ukáže co jíst při hubnutí, kolik si toho dát a jak si poradit i ve dnech, kdy nestíháš. Praktický základ celého dne najdeš také v článku [jídelníček na hubnutí pro ženy](/blog/jidelnicek-na-hubnuti-pro-zeny)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c5c1f9b3-37a7-4fdc-a6c3-19cf34c5eff6','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',4,'{"level":"h2","text":"Proč obecný jídelníček často nefunguje","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('73557dc0-d432-4dd6-b2c2-99556946ac27','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',5,'{"text":"Dvě ženy mohou mít stejný cíl, ale úplně jinou potřebu. Jedna celý den sedí v kanceláři, druhá je neustále na nohou. Jedna preferuje tři větší jídla, druhá potřebuje i svačinu. Jedna má ráda sladkou snídani, druhá po ní za hodinu cítí hlad."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('086975de-1fb5-4860-8c81-d366fa20bac8','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',6,'{"text":"Když obě dostanou stejný plán, minimálně jedna se mu bude muset výrazně přizpůsobovat. A čím více ústupků plán vyžaduje, tím menší je šance, že ho bude dlouhodobě používat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a07d532c-52b2-4f5e-9379-f284dfaa455e','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',7,'{"level":"h2","text":"Co musí jednoduchý jídelníček na hubnutí vyřešit","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('44d0cd1d-773e-4781-9ce9-3f034239b60c','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',8,'{"level":"h3","text":"1. Kolik jídla potřebuješ","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4138f5b7-d256-42bd-83bd-4a72f473f145','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',9,'{"text":"Nestačí vědět, že kuřecí maso, rýže a zelenina jsou vhodná kombinace. Potřebuješ znát také porci. Příliš malá porce vede k hladu a večernímu dojídání. Příliš velká může dlouhodobě brzdit výsledky, i když jsou všechny potraviny kvalitní."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('15447da4-a725-469c-b84e-3034bc387fc9','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',10,'{"level":"h3","text":"2. Jak rozložit jídlo během dne","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fc206b90-88ab-4940-a66d-5888efaeeb19','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',11,'{"text":"Některá žena potřebuje vydatnější snídani, jiná má ráno malý hlad a více jídla využije odpoledne. Jídelníček na míru by měl počítat s tvým režimem, ne tě nutit jíst v časech, které se do dne nehodí."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('580414d0-b292-48f8-90d1-858cfa32dc71','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',12,'{"level":"h3","text":"3. Co dělat, když nemáš čas vařit","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('869be67f-c26a-4cb5-8a96-46be255114e4','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',13,'{"text":"Jídelníček pro zaneprázdněné ženy nemůže být postavený pouze na receptech s dlouhou přípravou. Potřebuje rychlé snídaně, obědy do práce, studené večeře a nouzové varianty z běžných potravin."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d36ba048-4593-4d79-b397-fa868a12f327','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',14,'{"level":"h3","text":"4. Jak jídla obměňovat","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6cd2d9be-db1e-4aac-8da5-18d004204e33','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',15,'{"text":"Pevný plán funguje jen do chvíle, než ti některé jídlo přestane chutnat, surovina není v obchodě nebo rodina chce něco jiného. Proto potřebuješ chápat, co můžeš vyměnit a v jakém množství."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3ddfabab-11c0-4698-a5ef-ad47410d385c','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',16,'{"level":"h3","text":"5. Jak zapojit rodinná jídla","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('63cdbf3f-2047-4e23-8bc8-75c12b8b94fe','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',17,'{"text":"Nemusíš vařit dvě úplně odlišná jídla. Často stačí upravit množství, způsob přípravy nebo poměr jednotlivých částí na talíři. Dobře navržený jídelníček ti má práci ubírat, ne přidávat další hrnec."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('619ee24d-4a09-4f3f-990b-1277e4fca90f','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',18,'{"level":"h2","text":"Co jíst při hubnutí, aby tě jídlo zasytílo","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9c597b1c-1b52-4d88-81ef-7cd79848ea3a','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',19,'{"text":"Při hubnutí nemusíš hledat zázračné potraviny. Mnohem důležitější je skladba každého dne."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('cb9d1bd0-a8de-41ea-8264-9458a6b457fc','ca0d4cb8-a786-4d93-9d49-b730345c5c37','bullet_list',20,'{"items":["Bílkoviny v hlavních jídlech, například maso, ryby, vejce, mléčné výrobky, tofu nebo luštěniny.","Zelenina, ovoce a další zdroje vlákniny.","Přiměřené množství příloh a pečiva místo jejich automatického vyřazení.","Tuky v rozumné porci, ne nalévané nebo přisypávané bez kontroly.","Jídla rozložená tak, aby tě večer nedohnal celý hlad z předchozí části dne."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('21461fe3-a337-48fc-aad1-b348c878850e','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',21,'{"level":"h2","text":"Proč jídelníček z běžných potravin funguje lépe než „fit“ nákup","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3faeb23c-a2d9-4f77-8b5e-188f220c2bce','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',22,'{"text":"Čím více speciálních výrobků plán vyžaduje, tím dražší a náročnější může být. Hubnutí ale nestojí na proteinových sušenkách, exotických moukách ani potravinách z fitness obchodu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d3564a5b-1994-4573-b32c-6138997347c5','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',23,'{"text":"Většinu jídel lze postavit na potravinách, které už znáš: vejce, pečivo, vločky, brambory, rýže, maso, tvaroh, jogurt, luštěniny, ovoce a zelenina. Rozdíl dělá kombinace a porce."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f1b44593-c505-4c57-80e8-065fef8eea7a','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',24,'{"level":"h2","text":"Jak poznáš, že jídelníček není nastavený dobře","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b050777e-e139-41c1-987b-71e3045d39e2','ca0d4cb8-a786-4d93-9d49-b730345c5c37','bullet_list',25,'{"items":["Po většině jídel máš brzy znovu hlad.","Každý večer hledáš sladké nebo dojídáš, co je doma.","Vaření ti zabírá tolik času, že po několika dnech přestaneš.","Musíš odmítat všechna rodinná jídla a společné situace.","Nevíš, co dělat, když plánovaný recept nemůžeš připravit.","Při jednom vybočení máš pocit, že je celý den ztracený."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f0f4eb2d-761c-45c1-a43f-2d6431d9f6bb','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',26,'{"level":"h2","text":"Proč samotný jídelníček ke stažení nestačí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1de2d010-4775-449d-b27d-433892defe28','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',27,'{"text":"PDF se seznamem jídel ti může dát inspiraci. Neřekne ti ale, proč jsou porce nastavené právě tak, jak je můžeš měnit a co dělat, když některý den proběhne jinak."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('066f1a78-313f-4125-88af-07133825a718','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',28,'{"text":"Proto by kvalitní jídelníček pro zdravé hubnutí měl kromě samotného plánu obsahovat také návod k používání, výměny, plánování a řešení běžných situací. Cílem není být navždy závislá na jednom rozpisu. Cílem je postupně získat jistotu, jak si den poskládat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9a5b7dc9-770e-4aab-a3b0-23fa77494b38','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',29,'{"level":"h2","text":"Co získáš v Jídelníčku pro zdravé hubnutí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e92ce6a2-3999-4674-a048-841a5574647b','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',30,'{"text":"Jídelníček pro zdravé hubnutí Fit bez času je vytvořený pro ženy, které nechtějí další dietu, ale potřebují jasný systém. Získáš jídelníček na míru podle svého příjmu, konkrétní porce, recepty a ukázkové dny."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('59154b90-1486-4e7d-b180-2b94c93b4e55','ca0d4cb8-a786-4d93-9d49-b730345c5c37','paragraph',31,'{"text":"Součástí je také kalkulačka příjmu, 28denní průvodce, týdenní plánovač, tahák pro dny, kdy nestíháš, a tříměsíční přístup do aplikace Fit bez času PLUS. V aplikaci máš jídla, porce a svůj přehled na jednom místě."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e3a9dc17-5793-4ac8-82b4-a0febac84b3b','ca0d4cb8-a786-4d93-9d49-b730345c5c37','heading',32,'{"level":"h2","text":"Pro koho dává největší smysl","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('88dabf47-1741-4e78-b064-e80a26904dfa','ca0d4cb8-a786-4d93-9d49-b730345c5c37','bullet_list',33,'{"items":["Každý den přemýšlíš, co uvařit a kolik si toho dát.","Přes den jíš nahodile a večer tě dožene hlad.","Chceš jídelníček z běžných potravin, ne dietní experiment.","Potřebuješ plán, který se přizpůsobí práci a rodině.","Nechceš pouze počítat kalorie, ale vidět konkrétní jídla."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3b47738d-d8cb-4011-bd6a-240731ba7c78','ca0d4cb8-a786-4d93-9d49-b730345c5c37','cta',34,'{"eyebrow":"Jídelníček","title":"Chceš vědět, co a kolik jíst v běžném dni?","text":"Jídelníček pro zdravé hubnutí ti ukáže konkrétní porce, jídla z běžných surovin a praktický systém i pro dny, kdy nestíháš.","button_label":"Prohlédnout jídelníček","url":"https://www.fitbezcasu.cz/jidelnicek-pro-zdrave-hubnuti","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('33ae42a5-cd1a-40be-ae14-fa9805f804d5','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',1,'{"text":"Ráno rychle vyběhneš z domu. Ke snídani si dáš kávu, něco malého nebo vůbec nic. Oběd sníš ve spěchu a odpoledne se snažíš vydržet bez svačiny, protože chceš zhubnout. Večer ale přijde velký hlad. Po večeři máš chuť ještě na něco sladkého a celý den zakončíš pocitem, že jsi to zase nezvládla."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('26f610e7-dfbd-4e3e-b284-ad8ef00ec569','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',2,'{"text":"Jenže večerní hlad často nezačíná večer. Začíná už ráno a postupně se skládá z příliš malých porcí, nepravidelnosti a jídel, která tě na dlouho nezasytí. Pokud se večer opakovaně vrací i bez fyzického hladu, pomůže ti rozlišit také [hlavní spouštěče večerního vyjídání](/blog/jak-prestat-vecer-vyjidat-lednicku)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5c7becc5-64b4-4f39-a3e0-1205c98fd902','67cceed5-a712-4d31-a19e-d0745931cfca','heading',3,'{"level":"h2","text":"Tělo si o chybějící energii řekne","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c4a64148-1ae2-49b1-b57a-c7d0f672634b','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',4,'{"text":"Když chceš zhubnout, může se zdát logické jíst co nejméně. Menší snídaně, lehký oběd, žádná svačina a malá večeře. Chvíli to možná zvládneš. Tvoje tělo ale nevnímá, jestli máš dost pevnou vůli. Vnímá, kolik energie a živin během dne dostalo."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8bf88959-64e8-406b-b074-ebdc0fc497bc','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',5,'{"text":"Pokud jíš nepravidelně, porce jsou příliš malé nebo v jídlech chybí bílkoviny a vláknina, hlad se postupně zesiluje. Večer už se nerozhoduješ s klidnou hlavou. Jsi unavená, hladová a chceš něco rychlého a chutného."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('64bcf053-222e-49a1-9678-bbdb69cd1903','67cceed5-a712-4d31-a19e-d0745931cfca','heading',6,'{"level":"h2","text":"Zdravé jídlo ještě nemusí být dobře poskládané","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1f2f2150-26cb-4ee1-91ea-e8b8ec736544','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',7,'{"text":"Možná jíš potraviny, které považuješ za zdravé: jogurt s ovocem, zeleninový salát, celozrnné pečivo, ovesnou kaši nebo kuřecí maso. Přesto může být celkový jídelníček nastavený tak, že tě nezasytí."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5cf12869-a2a0-4544-9018-25d3f98cc695','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',8,'{"text":"Salát bez dostatečného množství bílkovin a přílohy může vypadat jako ideální oběd při hubnutí. Za dvě hodiny ale může přijít další hlad. Jogurt s trochou ovoce může být příliš malá snídaně. Smoothie vypité během několika minut tě nemusí zasytit stejně jako jídlo, které pomalu sníš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b7513ae5-87c1-49dd-8424-ee0cd99e9283','67cceed5-a712-4d31-a19e-d0745931cfca','heading',9,'{"level":"h2","text":"Co by mělo obsahovat hlavní jídlo","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e944a801-3ec5-4b43-bc3c-c13d152bfee6','67cceed5-a712-4d31-a19e-d0745931cfca','heading',10,'{"level":"h3","text":"Zdroj bílkovin","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7e459481-fcf1-4faa-b6df-0d56f70f9cd0','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',11,'{"text":"Bílkoviny pomáhají s nasycením a udržením svalové hmoty. Patří sem například maso, ryby, vejce, mléčné výrobky, luštěniny nebo tofu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('aa02871f-3fa3-4145-ba79-dc1f59204405','67cceed5-a712-4d31-a19e-d0745931cfca','heading',12,'{"level":"h3","text":"Přílohu nebo jiný zdroj sacharidů","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('46128f27-7b88-4b08-b4f6-ecf6be40664d','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',13,'{"text":"Sacharidy nejsou při hubnutí zakázané. Dodávají energii a pomáhají, aby ses po jídle cítila spokojená. Důležité je množství a celková skladba jídla."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('cf30d19b-c614-40f9-ab0c-ff99977ca04b','67cceed5-a712-4d31-a19e-d0745931cfca','heading',14,'{"level":"h3","text":"Zeleninu nebo ovoce","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2c296bf1-9baa-4f4c-b057-9572a65de0ec','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',15,'{"text":"Dodávají vlákninu, objem, vitaminy a minerální látky. Neměly by ale nahrazovat celé jídlo."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7e8b6859-e57f-4856-8847-29f4dac281b6','67cceed5-a712-4d31-a19e-d0745931cfca','heading',16,'{"level":"h3","text":"Přiměřené množství tuku","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ae5c18ef-751e-4db0-acc9-cf3e3dc31b92','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',17,'{"text":"Tuk je běžnou součástí vyváženého jídelníčku, ale má vysokou energetickou hodnotu. Proto je užitečné vědět, kolik oleje, ořechů, sýrů nebo pomazánek skutečně používáš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5871a803-ba8f-4d6a-be20-fdedf2fea587','67cceed5-a712-4d31-a19e-d0745931cfca','heading',18,'{"level":"h2","text":"Největší úleva není jíst dokonale. Je vědět, co dělat","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3fbf467b-69d3-4ebb-b24d-5a52e16ed8e3','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',19,'{"text":"Úleva přichází ve chvíli, kdy už nemusíš každé ráno přemýšlet, co budeš jíst, jak velká porce je pro tebe vhodná a co připravit, když nestíháš. Když máš jasný plán, nemusíš denně dělat desítky drobných rozhodnutí."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1ab1ad80-bfd3-475b-9919-9300483c0234','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',20,'{"text":"Víš, jak mohou vypadat tvoje porce. Máš připravené konkrétní možnosti a dokážeš si vybrat jídlo podle času i chuti. Právě takový systém může fungovat déle než několik dní."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e629cb04-0d21-47a6-90c3-4c395eba1c21','67cceed5-a712-4d31-a19e-d0745931cfca','heading',21,'{"level":"h2","text":"Pro koho je konkrétní jídelníček dobrým dalším krokem","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('53088424-fc3f-4637-9a3a-20aeeee3f3e6','67cceed5-a712-4d31-a19e-d0745931cfca','bullet_list',22,'{"items":["během dne často nevíš, co jíst","večer tě dohání hlad nebo chutě","tápeš ve velikosti porcí","jíš zdravě, ale výsledky nepřicházejí","nechceš každý den počítat všechno od začátku","potřebuješ recepty a konkrétní příklady","chceš se naučit jídla postupně obměňovat"]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('29be82ee-01b3-420e-bdd5-0f8bab8cc5c9','67cceed5-a712-4d31-a19e-d0745931cfca','heading',23,'{"level":"h2","text":"Získej Jídelníček pro zdravé hubnutí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3ea5def0-d157-42d4-83b7-3c72ad7d2b37','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',24,'{"text":"V programu získáš jídelníček na míru, konkrétní porce, recepty a praktický systém, který ti pomůže používat jídelníček i ve dnech, kdy nestíháš. Součástí jsou také nástroje a materiály, díky kterým nezůstaneš odkázaná jen na jeden pevný seznam jídel."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('772f4e13-b29b-4dc6-a74a-3dbc7b9d7c73','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',25,'{"text":"Naučíš se v jídelníčku orientovat, plánovat si týden a vybírat vhodné varianty podle aktuální situace. Navíc získáš tříměsíční přístup do aplikace Fit bez času PLUS, kde budeš mít svůj příjem, jídla, recepty a výsledky přehledně na jednom místě."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3070c5c1-2efb-46ff-ae3b-c996a4a746be','67cceed5-a712-4d31-a19e-d0745931cfca','paragraph',26,'{"text":"Jídelníček, konkrétní porce, praktické návody a 3měsíční přístup do aplikace PLUS za 1 490 Kč."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('eab3c1df-cb63-42d6-b5f3-f803573aa625','67cceed5-a712-4d31-a19e-d0745931cfca','cta',27,'{"eyebrow":"Jídelníček","title":"Chceš vědět, co a kolik jíst v běžném dni?","text":"Jídelníček pro zdravé hubnutí ti ukáže konkrétní porce, jídla z běžných surovin a praktický systém i pro dny, kdy nestíháš.","button_label":"Prohlédnout jídelníček","url":"https://www.fitbezcasu.cz/jidelnicek-pro-zdrave-hubnuti","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d761b02b-2289-4d0e-87af-0cc676ad3109','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',1,'{"text":"Začátek bývá snadný. Máš nový plán, chuť něco změnit a jasnou představu, jak se tentokrát budeš držet. Jenže motivace k hubnutí nevydrží každý den."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1910b086-869c-44aa-a358-711be5b600ef','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',2,'{"text":"Přijde náročná práce, špatný spánek, víkend mimo domov nebo období, kdy se výsledky zpomalí. Najednou se ti nechce připravovat jídlo ani cvičit. A právě tehdy se ukazuje, zda máš jen krátkodobé nadšení, nebo prostředí, které ti pomůže pokračovat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('31e328f8-2879-4fdf-bf02-8a41c70e3ecb','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',3,'{"text":"Jak vydržet u hubnutí? Nečekat, že se budeš každý den cítit stejně odhodlaná. Místo toho si vytvořit systém, který tě podrží i ve slabších dnech."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('913ae897-e2ec-4f9c-9636-8ed881b321a4','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',4,'{"level":"h2","text":"Proč motivace sama nestačí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3153e15c-65df-4969-8b8b-3292b8f10a6b','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',5,'{"text":"Motivace je pocit. Může ji spustit fotografie, nová zkušenost, číslo na váze nebo pocit, že už chceš něco změnit. Je užitečná pro start, ale není stabilní."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b38a82f8-2557-44c6-b697-83d90c0ac2bb','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',6,'{"text":"Když na ní postavíš celý plán, každý pokles energie začne vypadat jako problém. Ve skutečnosti je normální, že se ti někdy nechce. Dlouhodobá změna stojí na tom, co uděláš právě v těchto dnech."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('255572e4-496b-436f-a32f-d665bb5ee6e0','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',7,'{"level":"h2","text":"Co opravdu pomáhá vydržet u hubnutí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('31915ede-8ee0-471b-b819-02fad213bb20','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',8,'{"level":"h3","text":"1. Mít menší verzi každého kroku","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('87601f93-ee83-44e4-814c-fa6102e292b6','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',9,'{"text":"Nemáš energii na celý trénink? Dej si krátké protažení. Nestihla jsi připravit plánovaný oběd? Slož si jednoduchou krabičku z potravin, které máš po ruce. Nejde o dokonalou náhradu. Jde o to, aby jeden náročný den nepřerušil celý směr."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('37af3444-2143-40a5-b17e-ffae97bb1700','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',10,'{"level":"h3","text":"2. Nehodnotit týden podle jednoho jídla","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('841c469f-18c4-4ece-87e1-00594783fbfd','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',11,'{"text":"Jedna oslava, večeře venku nebo večer s větší chutí k jídlu nezruší všechny předchozí kroky. Největší problém často nevznikne samotným jídlem, ale následným pocitem, že už nemá cenu pokračovat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1ecd3833-9310-4412-857d-4fee70300f15','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',12,'{"level":"h3","text":"3. Vědět, k čemu se vrátit","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f115022b-2273-433b-9b90-f1669b0ecdb4','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',13,'{"text":"Když nemáš žádný základní plán, po výpadku znovu hledáš, kde začít. Pomáhá mít několik jednoduchých jídel, oblíbené krátké cvičení a jeden malý úkol, kterým navážeš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('42ce677e-9877-4390-af7d-d154c4babb07','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',14,'{"level":"h3","text":"4. Vidět změnu i mimo váhu","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8163c85d-0119-48ae-956e-807ec158b64c','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',15,'{"text":"Váha může několik dní kolísat. Pokud je jediným zdrojem motivace, snadno ztratíš chuť. Sleduj také energii, pravidelnost, kondici, obvody nebo to, jak rychle se po náročném dni vrátíš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('df02a8e2-e68d-419f-995f-8bec0054009b','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',16,'{"level":"h3","text":"5. Nebýt na všechna rozhodnutí sama","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('29a2e692-f4be-43a9-869e-d07265c8bd3a','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',17,'{"text":"Podpora při hubnutí není jen kontrola. Může znamenat místo, kde pravidelně dostáváš nový podnět, najdeš krátké cvičení, recept nebo připomenutí, že horší týden není konec."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('596e2e87-684b-4bbe-987b-76e7ddc68c62','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',18,'{"level":"h2","text":"Hubnutí krok za krokem místo neustálých restartů","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7970025d-d1f4-47b9-812a-0a6e8aa87231','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',19,'{"text":"Mnoho žen se pohybuje mezi dvěma režimy. Buď se snaží na sto procent, nebo nedělají nic. Takový přístup vytváří stále nové začátky a pocit, že žádný pokus nevydržel. Pokud tento vzorec znáš, projdi si také [proč u změny často nevydržíš](/blog/proc-nevydrzis)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('0d0cce40-9631-4802-a276-d3da93cad9fe','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',20,'{"text":"Hubnutí krok za krokem vypadá méně dramaticky. Jeden týden se soustředíš na snídani, další na pohyb, potom na večeře. Některé kroky opakuješ. Některé zjednodušíš. Díky tomu změna zapadá do života místo toho, aby s ním bojovala."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a5029be3-e4e2-4a29-bbc6-1aa8f90bbfdd','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',21,'{"level":"h2","text":"Jak si vytvořit prostředí, které podporuje zdravý životní styl","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('eb57e42e-b5fe-42d8-9dce-f382f235a19c','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','bullet_list',22,'{"items":["Měj krátká cvičení uložená na jednom místě.","Vyber si několik receptů, které zvládneš i bez dlouhé přípravy.","Připomínej si další malý krok, ne celý seznam povinností.","Obklop se lidmi, kteří řeší podobné situace bez soutěžení a tlaku.","Pravidelně se k tématu vracej, i když zrovna nejedeš naplno."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('70a0be6a-8471-4b35-9e30-90a011115efe','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',23,'{"level":"h2","text":"Co ti komunita může dát navíc oproti sociálním sítím","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('26d42a2c-e2ae-4987-9980-ccd3ef0e9ef2','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',24,'{"text":"Na sociálních sítích najdeš nekonečné množství tipů. Právě to může být problém. Každý den vidíš jiný směr, jiný trénink a jiné pravidlo. Místo jasnosti vzniká pocit, že pořád něco nevíš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fd9224d0-ed00-4566-a630-9a12814110a9','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',25,'{"text":"Komunita má výhodu v kontinuitě. Vracíš se na jedno místo, kde obsah dává dohromady pohyb, jídlo a praktické návyky. Nemusíš z každého příspěvku vytvářet nový plán."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e60205cc-94cd-471d-a900-0d9a865a4935','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',26,'{"level":"h2","text":"Komunita Fit bez času není další úkol navíc","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6830e0e9-af69-48be-ae58-d81899727f6b','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',27,'{"text":"Nemusíš splnit všechna cvičení, uvařit každý recept ani sledovat všechen obsah. Vybereš si to, co se hodí do tvého týdne. Jeden den krátký trénink, jindy protažení, rychlý recept nebo praktický návod."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8abb4043-24b8-4e12-80ef-03734f53cd37','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','paragraph',28,'{"text":"Pravidelně doplňovaný obsah ti pomůže neztratit zdravý životní styl z očí. Komunita zároveň vytváří prostor, kde vidíš, že i ostatní ženy mají práci, rodinu, výpadky a dny bez motivace."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('0d8a8733-b5bf-4c5d-9fc7-59b38b50391e','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','heading',29,'{"level":"h2","text":"Pro koho je členství vhodné","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('23d1441c-c1b4-4514-9ae9-4d6774f2b2c2','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','bullet_list',30,'{"items":["Víš přibližně, co dělat, ale chybí ti pravidelnost.","Nechceš další velký kurz ani přísný plán.","Potřebuješ nové nápady na pohyb a jídlo na jednom místě.","Pomáhá ti pocit, že na změně nepracuješ sama.","Chceš dlouhodobou inspiraci za nízkou měsíční částku."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('42f91558-b5e6-418b-ad8f-2decf01decd5','36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','cta',31,'{"eyebrow":"Komunita","title":"Hodila by se ti pravidelná inspirace a podpora?","text":"V Komunitě Fit bez času najdeš krátká cvičení, jednoduché recepty a podporu pro zdravější režim bez tlaku na dokonalost.","button_label":"Poznat Komunitu Fit bez času","url":"https://www.fitbezcasu.cz/komunita-fit-bez-casu","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8ba9fb3b-d1b3-4fcc-a642-9d7fd247b075','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',1,'{"text":"Pravděpodobně už víš, že by ses měla více hýbat, jíst pravidelněji a nezapomínat na odpočinek. Možná máš uložené desítky receptů a videí na cvičení. Informací máš dost. Přesto se po několika dnech nebo týdnech můžeš vrátit ke starému režimu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a311af9e-b05f-4c45-85b5-1ecdde082eb0','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',2,'{"text":"Ne proto, že bys nevěděla, co dělat. Ale protože vědět a opravdu to dlouhodobě dělat jsou dvě různé věci. Pokud teď řešíš hlavně kolísající odhodlání, začni článkem [jak se motivovat k hubnutí](/blog/jak-se-motivovat-k-hubnuti)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('093ded71-da21-4cad-a67c-bcb6c40e2506','c9609bb3-5bad-4c25-9551-9f42668bc778','heading',3,'{"level":"h2","text":"Začátek bývá jednodušší než pokračování","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('178f0a13-7a90-44c8-b2dd-8a8ae99ae133','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',4,'{"text":"Když se pro změnu nadchneš, první dny mohou jít snadno. Naplánuješ si jídlo, zacvičíš si a máš radost, že ses konečně pohnula správným směrem. Potom ale přijde týden, kdy je toho moc."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e14d577f-02eb-45b6-a9f3-18fead0547ee','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',5,'{"text":"Nestihneš nakoupit. Jeden den necvičíš. Druhý den sáhneš po rychlé večeři. O víkendu se režim rozpadne a v pondělí už máš pocit, že musíš začít od začátku."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('dde8a992-29fb-41bb-9a8e-5ba613e57a22','c9609bb3-5bad-4c25-9551-9f42668bc778','heading',6,'{"level":"h2","text":"Proč nestačí jednorázová motivace","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('32c5ea64-a97f-4b38-b1f0-80cd6f57dde6','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',7,'{"text":"Motivace se mění podle únavy, stresu i toho, co se právě děje doma a v práci. Proto je užitečné mít zdravější režim pravidelně na očích. Nový podnět, krátké cvičení, rychlý recept nebo zkušenost jiné ženy ti může pomoci udělat další malý krok."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8328ae94-12dc-4235-88e0-b6f1f98c2977','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',8,'{"text":"Někdy nepotřebuješ velkou proměnu. Stačí deset minut pohybu, připravená svačina, jednoduchá večeře nebo krátké protažení. Právě malé kroky rozhodují o tom, jestli budeš pokračovat i za měsíc."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('155f6ee2-e4e2-4a00-bfcc-b74f0671abdd','c9609bb3-5bad-4c25-9551-9f42668bc778','heading',9,'{"level":"h2","text":"Nemusíš dělat všechno najednou","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('956cd55d-d7e0-490f-845f-ae8180369d01','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',10,'{"text":"Zdravější životní styl se často prezentuje jako dlouhý seznam povinností. Cvičení, vaření, nákup, plánování, pitný režim, spánek a odpočinek. Když se snažíš změnit vše současně, vzniká další tlak."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c8d86c81-44ec-42f2-a0ac-a3f4c22243fc','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',11,'{"text":"Lepší je vybrat si podle aktuální situace. Máš více energie? Dej si domácí trénink. Jsi po dlouhém dni ztuhlá? Vyber si krátké protažení. Nevíš, co připravit k večeři? Sáhni po jednoduchém receptu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('46266f48-a5cb-48e8-ad34-88932386fbeb','c9609bb3-5bad-4c25-9551-9f42668bc778','heading',12,'{"level":"h2","text":"Proč je podpora tak důležitá","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('181ce995-d706-4f1b-9dc3-177d75cc5ed2','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',13,'{"text":"Když se snažíš něco změnit sama, snadno získáš pocit, že ostatním jde všechno lépe. Na sociálních sítích vidíš připravené jídlo, dlouhé tréninky a výsledky. Nevidíš obyčejné dny, kdy se někomu nechce, nestíhá nebo musí plán upravit."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c63a879f-b494-4c5d-88b3-31cb292e67dc','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',14,'{"text":"Komunita ti připomene, že změna nemusí být perfektní. Vidíš ženy, které také hledají cestu mezi prací, rodinou a péčí o sebe. A každý výpadek nemusíš brát jako konec."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('bb786b2a-7c9f-4767-8e18-b7a565f85813','c9609bb3-5bad-4c25-9551-9f42668bc778','heading',15,'{"level":"h2","text":"Co ti může pomoci vydržet","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('63569afb-ea61-4f6e-9713-3d891b95351d','c9609bb3-5bad-4c25-9551-9f42668bc778','bullet_list',16,'{"items":["jedno místo s praktickými materiály","pravidelná inspirace, která ti připomene tvůj cíl","možnost vybrat si podle času a energie","krátká cvičení a jednoduché recepty","prostředí žen s podobným cílem","možnost pokračovat bez tlaku na dokonalost"]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('18999d76-8f75-4f68-b7dd-7ca5bae85d89','c9609bb3-5bad-4c25-9551-9f42668bc778','heading',17,'{"level":"h2","text":"Komunita Fit bez času je místo pro dlouhodobé pokračování","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('26a7227c-9035-4352-8093-ffe2cc12eb8c','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',18,'{"text":"Komunita je určená ženám, které nechtějí další krátkodobý pokus, ale místo, kam se mohou pravidelně vracet. Najdeš v ní krátká domácí cvičení, protažení, recepty, ukázkové jídelníčky, návody, praktické materiály a podporu dalších žen."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3f7ea2b5-ea1e-4084-834b-0dddc87e626f','c9609bb3-5bad-4c25-9551-9f42668bc778','paragraph',19,'{"text":"Obsah si vybíráš podle toho, co zrovna potřebuješ. Nemusíš plnit pevně stanovený plán ani dohánět vše, co jsi nestihla. Komunita ti nebude slibovat dokonalý režim. Pomůže ti ale neztratit směr pokaždé, když přijde náročnější období."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('42d12ec7-a292-40d8-849e-fcdea301bffe','c9609bb3-5bad-4c25-9551-9f42668bc778','cta',20,'{"eyebrow":"Komunita","title":"Hodila by se ti pravidelná inspirace a podpora?","text":"V Komunitě Fit bez času najdeš krátká cvičení, jednoduché recepty a podporu pro zdravější režim bez tlaku na dokonalost.","button_label":"Poznat Komunitu Fit bez času","url":"https://www.fitbezcasu.cz/komunita-fit-bez-casu","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1cd02d9e-5324-42d4-b338-7560d2ce7917','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',1,'{"text":"Dáš si zdravou snídani, k obědu salát a večer něco lehkého. Přesto nevíš, jestli jíš příliš málo, nebo naopak více, než potřebuješ. Jeden den máš velký hlad, další den se snažíš jídlo omezit a o víkendu ztratíš přehled úplně."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('496e32de-1861-42cd-860d-cdd6bfd2691e','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',2,'{"text":"Bez konkrétních čísel je snadné řídit se jen pocitem. Jenže odhad porcí a celkového příjmu bývá nepřesný. Některá jídla mohou mít více energie, než čekáš. Jindy si naopak dáváš zbytečně malé porce a večer tě dožene hlad. Pro výchozí orientaci si přečti také [kolik kalorií denně jíst při hubnutí](/blog/kolik-kalorii-denne-pri-hubnuti)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('84459bc9-8520-428c-8534-b1a10d573236','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',3,'{"level":"h2","text":"Proč se na pocit nedá vždy spolehnout","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b8e54df6-9be5-4afe-9f27-073a62d20242','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',4,'{"text":"Hlad a sytost jsou důležité signály. Ovlivňuje je ale stres, spánek, rychlost jídla, složení jídel, pohyb i předchozí omezování. Můžeš proto sníst energeticky vydatné jídlo, které tě příliš nezasytí. Nebo si připravit velkou porci zeleniny, ve které chybí bílkoviny a dostatek energie."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('cab5a018-0a02-4c8d-9f93-41d5c1773e53','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',5,'{"text":"Nemusíš počítat každý gram po zbytek života. Pokud ale dlouhodobě nevíš, proč máš hlad nebo proč se výsledky neposouvají, několik dní poctivého zapisování ti může ukázat víc než další náhodná dieta."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5d81f6b4-70e1-473e-9483-e14fc2ce2b0a','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',6,'{"level":"h2","text":"Co ti může zapisování jídla odhalit","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9023b206-9d04-47c9-b24b-78d61207919f','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',7,'{"level":"h3","text":"Jíš méně bílkovin, než si myslíš","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fdddb35b-a910-49a1-8957-e239b6f46d52','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',8,'{"text":"Bílkoviny pomáhají s nasycením a měly by se během dne objevovat pravidelně. V zápisu snadno uvidíš, zda máš ve snídani, obědě a večeři skutečný zdroj bílkovin."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4063df8b-5f7a-4f06-9207-2ceb3b00fb8a','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',9,'{"level":"h3","text":"Nenápadně se sčítají malé porce","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('920915fe-0cdf-4d98-9750-b56a912a9218','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',10,'{"text":"Trocha oleje při vaření, několik ořechů, ochutnávání během přípravy jídla, slazený nápoj nebo větší množství sýra. Každá položka může působit nevýznamně, ale během dne se nasčítají."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4747de07-8019-4bcc-a83f-ba9ce211409b','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',11,'{"level":"h3","text":"Přes den jíš příliš málo","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2d95963e-af04-49e7-8427-668fbcd87023','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',12,'{"text":"Aplikace nemusí odhalit jen nadbytečný příjem. Může ukázat, že většinu dne jíš velmi málo a velkou část energie doplňuješ až večer. Díky tomu můžeš upravit snídani, oběd nebo svačinu místo boje s večerním hladem."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('81d722c0-2140-4b93-954b-9035a10f715c','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',13,'{"level":"h3","text":"Chybí ti vláknina","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d26b7e03-66d5-4ebc-aaeb-695de9d94e57','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',14,'{"text":"Pokud jíš málo ovoce, zeleniny, luštěnin a celozrnných potravin, může být jídelníček méně sytý a chudší na vlákninu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('260433de-754c-42d0-ac8d-f18c98344067','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',15,'{"level":"h3","text":"Víkendy vypadají jinak než pracovní dny","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9398ce61-0a2e-4a7d-b557-c374ee3eb973','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',16,'{"text":"Od pondělí do pátku můžeš mít režim stabilní, ale o víkendu se změní porce, pravidelnost i výběr jídel. Bez zápisu si rozdílu nemusíš všimnout."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('263a4368-a8ac-47f7-8a61-2d606431e922','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',17,'{"level":"h2","text":"Přehled nemá být trest","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('910a13ff-1fe6-48e6-af95-f49f5ebd1627','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',18,'{"text":"Zapisování nemá sloužit k tomu, aby sis po každém jídle něco vyčítala. Čísla nejsou hodnocení. Jsou to informace. Když vidíš, že ti chybí bílkoviny, můžeš je doplnit. Když zjistíš, že jsi přes den jedla málo, nemusíš se večer trestat za hlad. Příště upravíš celý den."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d5ed6c46-1dee-4995-9d24-fdb3b8c88454','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',19,'{"level":"h2","text":"Aplikace, nebo Plus?","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e12220fd-81e7-4701-85c7-136ad5eefb26','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',20,'{"level":"h3","text":"Aplikace","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7bf29001-3f58-41f9-a337-76c99d207c61','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',21,'{"text":"Je vhodná, když chceš vypočítat doporučený příjem, zapisovat vlastní jídla, sledovat kalorie a živiny, ukládat oblíbená jídla, kopírovat opakující se jídla a celé dny a sledovat vývoj váhy a tělesných mír. Aplikace ti dá nástroj a přehled. Jídla si volíš sama."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('916a9689-b27e-4d13-b8a5-8a281b346be6','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',22,'{"level":"h3","text":"Plus","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5708e13a-1e2d-4d90-b66d-b24ffb2cdea0','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',23,'{"text":"Plus je vhodný, když nechceš pouze zapisovat, ale potřebuješ také konkrétní inspiraci a jasnější vedení. K funkcím aplikace získáš kompletní jídelníček, konkrétní porce a vzorové dny. Nemusíš pokaždé přemýšlet, co si připravit a jak velké množství zvolit."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f2ac874e-4f0f-4377-888d-a7d11c404fe5','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','heading',24,'{"level":"h2","text":"Měj jídlo a výsledky na jednom místě","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9e03e615-90b6-46e2-aeae-397e8470c284','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',25,'{"text":"V aplikaci Fit bez času si vypočítáš doporučený příjem, zapíšeš jednotlivá jídla a hned vidíš, kolik kalorií a živin máš za den splněno. Oblíbená jídla, šablony a kopírování ti ušetří čas. Odděleně můžeš sledovat také vývoj váhy a tělesných mír."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5d297039-49a1-4d45-a2bb-39550ac12387','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',26,'{"text":"Nemusíš dál hádat, jestli jíš hodně, málo nebo ti v jídelníčku něco podstatného chybí. Podívej se na svůj den černé na bílém a začni upravovat to, co má skutečný vliv."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('78a593eb-c1ab-46f1-855e-909d5dc632ac','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','paragraph',27,'{"text":"Vyber si variantu Aplikace nebo Plus a vyzkoušej si hlavní funkce na 5 dní zdarma."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c411ba73-8231-40b2-8378-44fbc9173613','a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','cta',28,'{"eyebrow":"Aplikace Fit bez času","title":"Chceš mít jídlo, příjem a pokrok na jednom místě?","text":"V aplikaci si nastavíš výchozí příjem, zapisuješ jídlo a sleduješ kalorie, živiny, váhu i tělesné míry. Varianty si můžeš vyzkoušet na 5 dní zdarma.","button_label":"Vyzkoušet aplikaci zdarma","url":"https://platforma.fitbezcasu.cz/","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e8f4888b-054c-4718-a212-fc2f488784b5','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',1,'{"text":"Aplikace na počítání kalorií může být užitečný nástroj. Může ti ale také přidat další číslo, které každý večer hodnotíš jako úspěch nebo selhání."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d48d6131-396b-466f-9fb8-229a38c3f161','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',2,'{"text":"Rozdíl není jen v samotné aplikaci. Záleží také na tom, jak ji používáš. Smyslem zapisování jídla není získat perfektní den ani se trestat za každých deset kalorií navíc. Smyslem je konečně vidět, co během dne opravdu jíš a kde může vznikat hlad, nízký příjem bílkovin nebo nenápadně vysoké množství energie."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('01178672-1307-4d69-8f54-42e2e99bcafb','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',3,'{"text":"Dobrá aplikace na hubnutí ti má rozhodování zjednodušit. Ne tě nutit myslet na jídlo ještě více."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e95e72dd-a768-44fb-b43f-873f7868adb5','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',4,'{"level":"h2","text":"Proč odhad většinou nestačí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7565c204-66b8-40b1-86de-81b4067d8ede','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',5,'{"text":"Lidé běžně podhodnocují některé porce a jiné naopak přeceňují. Olej, sýry, ořechy, dresinky nebo nápoje mohou mít více energie, než čekáš. Zeleninový salát zase může působit jako velké jídlo, přestože v něm chybí bílkoviny a energie."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5234636a-3534-4727-8728-fb80b28ab88e','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',6,'{"text":"Několik dní poctivého zápisu proto často ukáže více než další zákaz. Uvidíš skutečný průběh dne a můžeš upravit konkrétní místo."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f62636d2-6213-43ba-b9af-32e1718b305e','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',7,'{"level":"h2","text":"Co by měla aplikace na zapisování jídla ukazovat","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1cd098c8-fff1-4e2f-b37d-30f3caa3e8b3','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','bullet_list',8,'{"items":["Doporučený energetický příjem odvozený od tvých údajů.","Kalorie i základní makroživiny: bílkoviny, sacharidy a tuky.","Vlákninu, která bývá v jídelníčku často přehlížená.","Průběžný stav během dne, ne pouze závěrečný součet.","Možnost ukládat oblíbená jídla a neopakovat stále stejný zápis.","Vývoj hmotnosti a tělesných mír odděleně od denního jídla."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fddec1f5-5907-4059-9726-85d942d4dbc8','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',9,'{"level":"h2","text":"Jak počítat kalorie bez zbytečné posedlosti","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7f466f52-1e80-4c13-95d2-d92691b87072','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',10,'{"level":"h3","text":"1. Začni několika běžnými dny","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3130ca11-07a2-4084-91bf-9f19d6d7ad3b','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',11,'{"text":"Nevybírej si jen den, kdy jíš ukázkově. Zapiš pracovní den, víkend a den, kdy nestíháš. Právě rozdíly mezi nimi ti mohou ukázat největší prostor ke změně."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('960aebda-f5c8-4b05-bf3b-39d17d393d99','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',12,'{"level":"h3","text":"2. Zapisuj co nejpoctivěji, ne co nejdokonaleji","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f326435d-2ecb-4913-ad3e-215be78bd6e7','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',13,'{"text":"Zapiš olej při vaření, mléko v kávě, ochutnávání i nápoje. Ne proto, abys měla výčitky, ale protože neúplná data vedou k chybným závěrům."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('befa400f-e1d4-4f9a-8bcd-6feee0407ff9','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',14,'{"level":"h3","text":"3. Sleduj souvislosti, ne jen konečné číslo","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1d9e4442-86b9-4850-8784-5169f5a95a9e','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',15,'{"text":"Když večer překročíš příjem, podívej se na celý den. Nechyběl ti oběd? Nebyla snídaně příliš malá? Nezůstala většina kalorií v jídlech, která tě málo zasytila?"}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('712a0668-0452-48a3-8e29-7a183a5d6464','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',16,'{"level":"h3","text":"4. Neopravuj každý den","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('77216b1f-7a84-4614-a9a6-c139d59f9530','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',17,'{"text":"Jeden den není dostatek dat. Kalorický příjem i hmotnost přirozeně kolísají. Hodnoť opakující se vzorec za více dní, ne jednotlivý výsledek."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a2ff47dc-0daf-4a0e-a3ab-b06711821e2d','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',18,'{"level":"h3","text":"5. Používej aplikaci jako učební nástroj","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4dac2a59-df80-41a9-aaf8-5b657545aef5','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',19,'{"text":"Postupně začneš rozpoznávat porce, zdroje bílkovin a potraviny, které ti zaberou velkou část příjmu. Aplikace nemusí být doživotní kontrolor. Může být způsob, jak se naučit lépe rozhodovat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e22735a9-5127-494a-a8cd-af56f2a1f29c','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',20,'{"level":"h2","text":"Bazální metabolismus není tvůj jídelníček","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('0ffb39ad-a100-4282-8852-137e1bfb9f89','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',21,'{"text":"Mnoho aplikací nejdříve vypočítá bazální metabolismus. Ten představuje odhad energie potřebné pro základní fungování těla v klidu. Není to automaticky částka, kterou máš jíst při hubnutí."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('91b1524a-3b56-4d94-8627-9345bae7e990','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',22,'{"text":"Pro nastavení příjmu je potřeba zohlednit také běžnou aktivitu. Teprve potom lze vytvořit přiměřený kalorický deficit. Proto je důležité, aby aplikace neukazovala pouze jedno izolované číslo, ale pomohla ti převést ho do celého dne. Podrobněji tento princip vysvětluje článek o tom, [jak nastavit kalorický deficit](/blog/kaloricky-deficit)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fd73b432-8074-453f-9e46-e01b90309d09','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',23,'{"level":"h2","text":"Aplikace na hubnutí zdarma: co během zkoušky ověřit","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('20dcde4f-1748-4140-b214-34d28dfede60','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','bullet_list',24,'{"items":["Je pro tebe zapisování rychlé a přehledné?","Najdeš běžná jídla a recepty, které používáš?","Dokážeš opakovaná jídla uložit nebo zkopírovat?","Rozumíš tomu, co ti jednotlivé hodnoty říkají?","Pomáhá ti aplikace udělat rozhodnutí, nebo jen zobrazuje čísla?"]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('c973a856-7b80-400c-90d8-f93ea3ddb8a9','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',25,'{"level":"h2","text":"Rozdíl mezi Aplikací a Plus","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('34a04939-93c0-48d2-8085-23b465e0efe9','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',26,'{"level":"h3","text":"Aplikace","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ba889b45-bda9-4c99-b220-9a71266d0b94','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',27,'{"text":"Aplikace je vhodná, když si chceš vlastní jídla vybírat sama. Spočítáš si doporučený příjem, zapisuješ jídlo a sleduješ kalorie, bílkoviny, sacharidy, tuky a vlákninu. Oblíbená jídla, šablony a kopírování celých dnů zrychlují opakované zápisy."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1917980d-fcfd-4091-89fd-85a81254e70e','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',28,'{"level":"h3","text":"Plus","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('73d2d33d-ae6a-4932-a31a-e645dde98162','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','paragraph',29,'{"text":"Plus přidává konkrétní jídelníček, porce a vzorové dny. Je vhodný, pokud nestačí vědět, kolik jsi snědla. Potřebuješ také inspiraci, co si za svůj příjem skutečně připravit."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1afb60ff-85a7-4370-a712-21af5ef07909','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','heading',30,'{"level":"h2","text":"Pro koho aplikace dává největší smysl","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e5acf107-abf7-4ae1-8b64-3923eb647870','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','bullet_list',31,'{"items":["Nevíš, kolik energie během dne skutečně přijmeš.","Máš pocit, že jíš málo, ale výsledky tomu neodpovídají.","Chceš zkontrolovat bílkoviny, vlákninu a další živiny.","Opakuješ podobná jídla a nechceš je pokaždé zadávat znovu.","Chceš sledovat pokrok i pomocí tělesných mír."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('61e05942-7817-4304-9e68-7eb14e316a09','1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','cta',32,'{"eyebrow":"Aplikace Fit bez času","title":"Chceš mít jídlo, příjem a pokrok na jednom místě?","text":"V aplikaci si nastavíš výchozí příjem, zapisuješ jídlo a sleduješ kalorie, živiny, váhu i tělesné míry. Varianty si můžeš vyzkoušet na 5 dní zdarma.","button_label":"Vyzkoušet aplikaci zdarma","url":"https://platforma.fitbezcasu.cz/","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2eef8a7b-f838-406b-aeb4-17825c38deb6','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',1,'{"text":"K snídani si dáváš ovesnou kaši. K obědu kuřecí maso se zeleninou. Sladkosti se snažíš omezovat a místo bílého pečiva kupuješ celozrnné. Přesto se váha dlouhodobě nehýbe."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('cb5bacab-3fc1-4c73-a063-23ff0d2d4096','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',2,'{"text":"Začneš proto ubírat další jídlo, vynechávat přílohy nebo hledat potravinu, která ti údajně brání zhubnout. Jenže problém nemusí být v jedné konkrétní potravině. Často je ukrytý v celkové skladbě dne, velikosti porcí, pravidelnosti nebo drobnostech, které si při běžném jídle ani neuvědomuješ."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6ec2b9a9-46a6-4c79-9652-74108b792092','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',3,'{"level":"h2","text":"1. Zdravé potraviny mají stále energetickou hodnotu","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d565f631-603c-43b0-8b36-65f04d728309','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',4,'{"text":"Ořechy, avokádo, kvalitní olej, sýry, ořechová másla nebo domácí granola mohou být součástí vyváženého jídelníčku. To ale neznamená, že na jejich množství nezáleží. Olej nalitý do pánve od oka, větší hrst ořechů a několik plátků sýra mohou výrazně zvýšit energetickou hodnotu jídla."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('bd098394-6198-41af-a7d1-6f2b6410417f','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',5,'{"level":"h2","text":"2. Přes den jíš příliš málo","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('0358f69d-4510-407e-a565-299813694004','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',6,'{"text":"Častý scénář vypadá takto: ráno jen káva, k obědu malý salát a odpoledne nic. Večer přijde hlad, ochutnávání při vaření, větší večeře a chuť na sladké. Když hodnotíš jen večer, můžeš mít pocit, že ti chybí disciplína. Když se podíváš na celý den, uvidíš, že tělo dohání energii, kterou dříve nedostalo."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3cdc7691-abe1-46f0-9112-68e3b79d7a9b','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',7,'{"level":"h2","text":"3. V jídlech chybí bílkoviny","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9e6d3f27-94e2-4287-b808-517f239dfa84','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',8,'{"text":"Můžeš jíst relativně kvalitně, ale pokud v hlavních jídlech chybí dostatečné množství bílkovin, hlad se může vracet příliš rychle. Ovoce, samotná zelenina nebo pečivo s malým množstvím pomazánky nemusí vytvořit syté jídlo."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('805697c5-c7cf-4203-b3fe-901377c089c6','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',9,'{"level":"h2","text":"4. Porce odhaduješ jinak, než vypadají ve skutečnosti","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('74728b86-51e3-4c9e-83d4-eacdb51df29b','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',10,'{"text":"Můžeš mít pocit, že sis dala jen trochu těstovin, malou porci dresinku nebo jeden kousek pečiva. Bez konkrétního pohledu na celý jídelníček ale nevíš, co se během dne skutečně sečetlo. Stejně tak si můžeš dávat zbytečně málo přílohy a potom hledat energii v drobném zobání."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2d7a361c-4baa-4ee0-b418-3d69975d19d8','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',11,'{"level":"h2","text":"5. Nezapočítáváš nápoje a ochutnávání","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6a3c244b-4c7e-42e5-bbeb-d6b38db887a2','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',12,'{"text":"Káva s mlékem, džus, slazená limonáda nebo alkohol se často nevnímají stejně jako jídlo. Podobné je to s ochutnáváním při vaření, dojídáním po dětech nebo několika sousty mezi hlavními jídly. Jednotlivě nejde vždy o velké množství, ale pokud se opakují každý den, mohou výsledný příjem změnit."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('85f4bcb2-f6fe-4cde-a7de-b1f9bcf37dfb','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',13,'{"level":"h2","text":"6. Každý den vypadá úplně jinak","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('539d9299-3326-471f-9926-d4f9bf2f8a27','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',14,'{"text":"Jeden den se snažíš jíst co nejméně. Další den máš velký hlad. O víkendu se režim uvolní a v pondělí začneš znovu omezovat porce. Takové střídání ztěžuje hubnutí i schopnost poznat, kolik jídla skutečně potřebuješ."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('93176914-a4a7-4af7-b79d-466f158c7a15','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',15,'{"level":"h2","text":"7. Zaměřuješ se na nesprávný problém","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8be22573-9054-4873-bd68-3257f89ed4b9','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',16,'{"text":"Možná řešíš pečivo, přestože hlavním problémem je nízký příjem bílkovin. Možná vynecháváš večeři, přestože potřebuješ větší oběd. Možná kupuješ drahé zdravé potraviny, ale během dne nemáš žádný pravidelný systém."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('08847f0b-de26-4767-8580-53d10eef3fec','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',17,'{"level":"h2","text":"Obecné rady ti neřeknou, co se děje právě u tebe","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d83315ad-0598-4a32-ba43-99c1221eb4f8','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',18,'{"text":"Na internetu najdeš stovky seznamů nejčastějších chyb při hubnutí. Stále ale nemusíš vědět, která chyba se týká právě tebe, co už máš nastavené dobře, co má největší vliv a co změnit jako první. Rozdíly mezi dostupnými službami shrnuje také přehled, [jakou podporu při hubnutí vybrat](/blog/podpora-pri-hubnuti-jakou-vybrat)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b608b647-1147-4238-9707-3e77c8da53f7','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',19,'{"text":"Když se snažíš opravit všechno najednou, může být jídelníček ještě složitější. Mnohem praktičtější je najít několik konkrétních změn, které dávají největší smysl pro tvůj režim."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('50501bc7-fd73-4f30-8802-a88e7e11aa60','9d363cb7-74e8-489a-9b38-2c7bdc428de4','heading',20,'{"level":"h2","text":"Nech si svůj jídelníček osobně zhodnotit","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('bb7d0daa-6629-4067-b3bb-d143ce3fbf23','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',21,'{"text":"Při osobním zhodnocení se nepodíváme na obecný ukázkový jídelníček. Podíváme se na to, co skutečně jíš ty. Zjistíš, co máš nastavené dobře, kde může vznikat hlad, zda jsou porce a skladba jídel vyvážené a které části dne ti komplikují hubnutí."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e1481f21-b7d9-4c26-96d1-d98245dac18e','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',22,'{"text":"Dostaneš jasná doporučení a konkrétní priority, ne další dlouhý seznam zákazů. Nemusíš dál zkoušet náhodné změny a čekat, jestli některá zabere. Můžeš konečně zjistit, co se ve tvém jídelníčku skutečně děje."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6179e718-a032-425a-b52d-af3beb046109','9d363cb7-74e8-489a-9b38-2c7bdc428de4','paragraph',23,'{"text":"Získej konkrétní pohled na svůj skutečný jídelníček a jasné kroky, které můžeš začít používat v běžném dni."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('868ca00f-fbfb-4424-8c4b-4e7755dfe3d2','9d363cb7-74e8-489a-9b38-2c7bdc428de4','cta',24,'{"eyebrow":"Osobní rozbor jídelníčku","title":"Chceš zjistit, co ve tvém jídelníčku brzdí výsledky?","text":"Z pěti běžných dní zjistíme, co už funguje, kde vzniká největší problém a které konkrétní změny mají pro tebe největší smysl.","button_label":"Zjistit více o osobním rozboru","url":"/nabidka-podpory/osobni-rozbor-jidelnicku","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('51d66f85-10e1-4cd1-b0ea-4871fe716bb0','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',1,'{"text":"Jíš zdravěji než dřív. Sladkosti omezuješ, porce se snažíš hlídat a některé dny máš pocit, že jíš opravdu málo. Přesto se váha nehýbe tak, jak očekáváš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('02a603e2-1f26-4be8-9595-276488f6ec6b','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',2,'{"text":"V této chvíli je lákavé ubrat další jídlo, vyřadit pečivo nebo přidat nový zákaz. Jenže pokud neznáš skutečnou příčinu, můžeš stále zpřísňovat jídelníček a přitom míjet místo, které výsledek ovlivňuje nejvíc. Než příjem dál snížíš, ověř si, [jak funguje rozumný kalorický deficit](/blog/kaloricky-deficit)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6eddd08c-490b-47e2-b0a6-cac73f195682','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',3,'{"text":"Otázka „proč nehubnu“ nemá jednu univerzální odpověď. Potřebuješ se podívat na celý den, opakující se týdny a konkrétní způsob, jakým jíš ty."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f4ed0466-e5ee-4dc2-939e-bc5aa1642b26','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',4,'{"level":"h2","text":"Proč se vlastní jídelníček hodnotí tak těžko","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e1450669-3df4-4a15-ac5f-3ee083bfe931','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',5,'{"text":"Když se díváš na své jídlo, vidíš jednotlivé situace. Zdravou snídani, salát k obědu nebo několik čtverečků čokolády. Hůře se ale vnímají souvislosti: jak malý oběd ovlivnil večer, kolik se sečetlo drobným ochutnáváním nebo zda je víkend úplně jiný než pracovní týden."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d579814d-7c23-4ce6-a362-a74f206a8005','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',6,'{"text":"Navíc máme tendenci věnovat pozornost tomu, co považujeme za problém. Můžeš řešit sacharidy, přestože hlavním slabým místem je nízký příjem bílkovin a nepravidelnost."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('45fbade4-1fa3-4786-aaca-968e956e7dc5','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',7,'{"level":"h2","text":"Sedm důvodů, které mohou stát za tím, že se ti nedaří zhubnout","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e3186fa4-4cfd-41f3-b16c-d725c08e1362','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',8,'{"level":"h3","text":"1. Jíš málo přes den a hodně večer","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a6740a9e-54cb-4be6-8337-af9f398b96c2','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',9,'{"text":"Ráno káva, k obědu lehký salát a odpoledne nic. Večer přijde hlad, ochutnávání při vaření a chuť na sladké. Celkový den může být energeticky vyšší, než působí, přestože většinu dne máš pocit omezení."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2403c3cb-2edf-4ffb-9d79-24eb50fd7569','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',10,'{"level":"h3","text":"2. Zdravé potraviny používáš v množství, které se rychle sečte","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6769431d-83ff-4d5b-83d3-06ba9f70f8c4','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',11,'{"text":"Ořechy, sýry, olej, avokádo nebo domácí granola mohou být kvalitní součástí jídelníčku. Energetická hodnota ale nezmizí jen proto, že je potravina zdravá."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('17628e8e-6fe3-4073-94ad-d5d094422cc1','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',12,'{"level":"h3","text":"3. Chybí ti bílkoviny a sytost","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7b443a97-4e3d-44dc-9e94-f9e0cecd5bd9','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',13,'{"text":"Když máš v jídle málo bílkovin, může se hlad rychle vracet. Pak jíš častěji nebo hledáš něco malého mezi jídly. Jednotlivá sousta se špatně pamatují, ale v součtu mohou být důležitá."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e64c421e-c860-4b0d-9d3c-c8cd1bc8c54e','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',14,'{"level":"h3","text":"4. Víkend ruší deficit z pracovních dnů","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fcbe2f95-d595-4bfa-928e-0476ca46fdf0','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',15,'{"text":"Od pondělí do pátku jíš velmi střídmě. O víkendu jsou porce větší, přibude alkohol, restaurace nebo průběžné občerstvení. Neznamená to, že víkend nesmíš užít. Potřebuješ ale vědět, jak vypadá celý týden."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('cb400b0a-6ba3-4517-ba91-69e1bb720677','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',16,'{"level":"h3","text":"5. Zápis nebo odhad nejsou přesné","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('8d4cf806-ad01-4e2e-b99a-0f0bda00b1ed','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',17,'{"text":"Lžíce oleje, mléko v několika kávách, dresink, dojídání po dětech nebo větší porce přílohy mohou zůstat mimo pozornost. Kontrola jídelníčku často ukáže, že problém není v hlavních jídlech, ale v detailech kolem nich."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('e87e71e9-09ff-49d5-a69a-f6da030c3f21','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',18,'{"level":"h3","text":"6. Čekáš rychlejší vývoj, než je reálné","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d4ec87ee-9ac6-486c-99f3-2513f3cbdcdd','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',19,'{"text":"Váha reaguje také na vodu, cyklus, sůl, trávení a změny pohybu. Několik dnů bez poklesu neznamená, že se nic neděje. Problém vzniká, když podle každého vážení měníš příjem a nikdy nedáš jednomu nastavení čas."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ef92e82b-ce84-41a2-a81e-f2e292dfcfb9','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',20,'{"level":"h3","text":"7. Řešíš číslo, ale ne svůj režim","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b0b14514-113b-4f20-beaa-fe4aa0ec1e49','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',21,'{"text":"Můžeš mít dobře spočítaný příjem, ale pokud plán vyžaduje vaření, které nezvládáš, nebo jídla, která ti nechutnají, nebudeš ho dodržovat. Praktická použitelnost je součást výsledku."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4cde43d3-03f1-4004-9b95-c1b211f1d6ec','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',22,'{"level":"h2","text":"Proč obecný seznam chyb nestačí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3972d2e5-a52e-4cbf-8dc7-5d502ce254c4','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',23,'{"text":"Když si přečteš deset nejčastějších chyb při hubnutí, pravděpodobně se poznáš v několika z nich. Stále ale nevíš, která má u tebe největší význam a co máš upravit jako první."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('94c19e61-4657-4e6d-9c95-c5118173dfa3','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',24,'{"text":"Pokus opravit všechno současně obvykle vede k ještě složitějšímu režimu. Mnohem účinnější je najít dvě nebo tři konkrétní změny, které odpovídají tvému jídelníčku a dni."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('0353714f-c2f3-4e7d-bb52-cd456ffade2d','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',25,'{"level":"h2","text":"Jak probíhá užitečný rozbor jídelníčku","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('dc58b4c2-d34b-4c75-b59d-99d10e605045','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',26,'{"text":"Rozbor jídelníčku se nedívá jen na to, zda jsi jedla „správné“ potraviny. Sleduje celý obraz: množství, skladbu, pravidelnost, bílkoviny, vlákninu, hlad, chutě a situace, ve kterých se plán rozpadá."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1462e26f-e9ad-475c-b9f7-0961158379cd','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','bullet_list',27,'{"items":["Co už máš nastavené dobře a není potřeba měnit.","Kde v průběhu dne vzniká největší hlad.","Zda jsou hlavní jídla dostatečně sytá.","Které položky mohou nenápadně zvyšovat příjem.","Jaké změny budou mít největší efekt při nejmenší složitosti.","Co upravit jako první a co zatím nechat být."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fa1a454b-1dde-4602-849c-baa68fce34bc','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',28,'{"level":"h2","text":"Osobní zhodnocení není nový zákazový seznam","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('04e514fa-6b35-4759-99fb-f02543b2a4a9','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',29,'{"text":"Cílem není označit jídla za dobrá a špatná. Cílem je vysvětlit, proč se některé situace opakují a jak je změnit bez zbytečného přidávání pravidel."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4c5f5898-9cab-46fa-a827-089a4183b01c','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','paragraph',30,'{"text":"Možná zjistíš, že nepotřebuješ ubrat večeři, ale přidat oběd. Možná není problém pečivo, ale malé množství bílkovin. Nebo jídelníček funguje dobře a je potřeba dát vývoji více času."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d30763d2-e926-4e28-8884-42aaccca6155','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','heading',31,'{"level":"h2","text":"Pro koho je osobní zhodnocení vhodné","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('294cdbfd-4819-46cc-802e-c5cf9e9dba4c','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','bullet_list',32,'{"items":["Máš pocit, že jíš zdravě, ale výsledek nepřichází.","Nevíš, zda jíš příliš málo, nebo příliš mnoho.","Pravidelně tě trápí hlad nebo chutě.","Nechceš další obecný plán, ale pohled na svůj skutečný den.","Potřebuješ vědět, co změnit jako první."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9203c3ed-14f8-4f58-8007-2276a03b23de','99b3c520-57b1-4dba-a726-2d7ab97a3fc8','cta',33,'{"eyebrow":"Osobní rozbor jídelníčku","title":"Chceš zjistit, co ve tvém jídelníčku brzdí výsledky?","text":"Z pěti běžných dní zjistíme, co už funguje, kde vzniká největší problém a které konkrétní změny mají pro tebe největší smysl.","button_label":"Zjistit více o osobním rozboru","url":"/nabidka-podpory/osobni-rozbor-jidelnicku","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5f67f008-30ce-4cec-88e4-605bfcfe419f','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',1,'{"text":"Na papíře může jídelníček vypadat jednoduše. Máš připravené porce, recepty a přibližně víš, jak by měl tvůj den vypadat. První dny se snažíš plán dodržovat. Potom ale přijdou situace, které v žádném ukázkovém jídelníčku nejsou."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('67238240-0b5a-4f6c-b34c-1424c0fa5fa0','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',2,'{"text":"Nestihneš si připravit oběd. Rodina chce jiné jídlo. Večer jdeš do restaurace. Máš větší hlad než obvykle. Některá jídla ti nechutnají. Váha se jeden týden nepohne a ty nevíš, jestli máš něco změnit."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d2eb486c-ed2d-4f6d-9b91-b48d46c36b4e','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',3,'{"text":"Právě v těchto chvílích většina žen nepotřebuje další obecnou radu. Potřebuje možnost popsat svou konkrétní situaci a zjistit, co s ní. Jednotlivé možnosti můžeš porovnat v přehledu, [jakou podporu při hubnutí vybrat](/blog/podpora-pri-hubnuti-jakou-vybrat)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('bd6a1c9c-8bb7-428a-8f50-bbe18e945838','bf8cb301-196c-4833-9b47-04e765c50ee5','heading',4,'{"level":"h2","text":"Plán nemůže předvídat každý tvůj den","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ecb8b80f-fdc5-49f6-a6c9-c25bd22528ad','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',5,'{"text":"Ani sebelepší jídelníček nedokáže dopředu popsat všechny situace, které během měsíce nastanou. Jednou máš čas vařit. Jindy potřebuješ jídlo připravené za deset minut. Některý týden se více hýbeš. Další týden jsi unavená a většinu času sedíš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2bd72450-659b-4d88-a51b-9e1c95d864c9','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',6,'{"text":"Jídelníček proto nemá fungovat jako přísný rozpis, který buď přesně dodržíš, nebo jsi selhala. Měl by být základem, který se naučíš používat a upravovat podle svého života. A právě tato část bývá nejtěžší."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('67fe9b28-960a-41e5-9de0-a4b91ff80136','bf8cb301-196c-4833-9b47-04e765c50ee5','heading',7,'{"level":"h2","text":"Nejčastější otázky přicházejí až během používání","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('72c6c06f-8ff6-4057-9d3b-1ab487fb8a37','bf8cb301-196c-4833-9b47-04e765c50ee5','bullet_list',8,'{"items":["Čím můžu nahradit jídlo, které mi nechutná?","Co si mám dát, když nestíhám připravit oběd?","Můžu si porce přesunout mezi jednotlivými jídly?","Co dělat, když mám večer pořád hlad?","Jak si poskládat jídlo v restauraci?","Je normální, že se váha několik dní nehýbe?","Jak se vrátit po víkendu, kdy jsem plán nedodržela?"]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b6b62ba5-afae-4450-85c5-2e66cba5b872','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',9,'{"text":"Bez podpory můžeš začít hledat odpovědi na různých místech. Každý zdroj ale doporučí něco jiného. Jeden radí ubrat sacharidy, druhý přidat půst, třetí vyřadit pečivo. Místo většího klidu vznikne další zmatek."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('50de3a3b-66a6-4587-b12e-54be17400756','bf8cb301-196c-4833-9b47-04e765c50ee5','heading',10,'{"level":"h2","text":"Jedna drobná úprava může změnit celý týden","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a7b5afbd-779e-4e0b-acf2-6b95881e904a','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',11,'{"text":"Podpora není jen o tom, že ti někdo řekne, zda děláš věci správně. Často stačí najít jedno místo, které ti komplikuje celý režim. Může to být příliš malá snídaně, chybějící plán pro pracovní dny nebo recepty, jejichž příprava je pro tvůj režim příliš složitá."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('566d1849-c802-4507-a179-f94d1ae88ff6','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',12,'{"text":"Když problém pojmenuješ včas, nemusíš čekat několik týdnů, než zjistíš, že současný způsob nefunguje. Uděláš konkrétní úpravu a můžeš pokračovat."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('762ebdf0-42f8-4351-9d46-a44c0049d02b','bf8cb301-196c-4833-9b47-04e765c50ee5','heading',13,'{"level":"h2","text":"Proč pomáhá pravidelné týdenní shrnutí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('ab2e192e-134e-48b7-b883-fb82b289f58b','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',14,'{"text":"Během jednoho dne se může stát cokoliv. Jeden horší den proto neříká, že je celý plán špatně. Při pohledu na celý týden lépe uvidíš, co se ti podařilo, kde ses opakovaně zasekla, v jaké části dne máš největší hlad a co ti zabírá příliš mnoho času."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5b0e4613-2151-4112-a52e-fa60177cebe7','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',15,'{"text":"Týdenní zpětná vazba ti pomůže nesoudit vše podle jednoho čísla na váze nebo jednoho náročného večera. Místo ukončení celého pokusu uděláš konkrétní úpravu pro další týden."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('301fa3cc-cfbd-4676-9110-6b86adfa3792','bf8cb301-196c-4833-9b47-04e765c50ee5','heading',16,'{"level":"h2","text":"Podpora neznamená kontrolu ani hodnocení","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('16c62323-8d6f-42a3-a1ce-db03b5978c9c','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',17,'{"text":"Možná nechceš nikomu posílat své výsledky, protože máš strach, že tě bude soudit za jídlo, které se do plánu nevešlo. Smyslem podpory ale není hledat chyby a rozdávat známky. Smyslem je pochopit, proč určitá situace nastala a jak ji příště vyřešit snadněji."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2ae8f8a9-f0a2-49b1-a7bb-857a24e9d2ad','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',18,'{"text":"Když si dáš dort na oslavě, nepotřebuješ pokárání. Potřebuješ vědět, že jedna oslava nerozhoduje o výsledku a že další den nemusíš hladovět. Když nestíháš vařit, nepotřebuješ slyšet, že si máš lépe plánovat čas. Potřebuješ konkrétní rychlou variantu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('50541150-22d5-42af-892c-d4c82431ba15','bf8cb301-196c-4833-9b47-04e765c50ee5','heading',19,'{"level":"h2","text":"Čtyři týdny, během kterých nebudeš na otázky sama","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9dda6b6a-f906-4d27-af60-865c108357ba','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',20,'{"text":"Ve 4týdenní e-mailové podpoře budeš mít prostor pravidelně shrnout svůj týden, popsat, co se ti podařilo a kde sis nevěděla rady. Dostaneš konkrétní zpětnou vazbu a doporučení pro další postup."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f56284bb-9a1d-46b9-bcef-7d7718e8495e','bf8cb301-196c-4833-9b47-04e765c50ee5','paragraph',21,'{"text":"Součástí je také přístup do WhatsAppové skupiny, kde se můžeš kdykoliv zeptat na otázku, která se objeví během běžného dne. Podpora je vhodná hlavně tehdy, když už máš jídelníček nebo základní plán, ale chceš si být jistá, že ho používáš správně a dokážeš ho přizpůsobit svému životu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1da46e0e-4bfd-4ecb-8c2b-4b8c3a38aff7','bf8cb301-196c-4833-9b47-04e765c50ee5','cta',22,'{"eyebrow":"4týdenní podpora","title":"Nechceš všechny otázky při změně řešit sama?","text":"Během čtyř týdnů získáš pravidelnou zpětnou vazbu, jasnou prioritu pro další týden a možnost průběžně řešit konkrétní situace.","button_label":"Zjistit více o 4týdenní podpoře","url":"/nabidka-podpory/emailova-konzultace","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('f72ec199-744a-4822-8b64-72e994256189','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',1,'{"text":"Mít jídelníček je jedna věc. Používat ho během pracovního týdne, návštěv, únavy a nečekaných změn je věc druhá."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('a49aecba-ed9e-4cfb-b657-8e77d06b8cb1','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',2,'{"text":"Na začátku může plán působit jasně. Víš, co si připravit, a první dny se snažíš všechno dodržet. Potom ale nestihneš oběd, rodina chce jiné jídlo, jdeš do restaurace nebo máš večer větší hlad. Najednou nevíš, jestli můžeš jídlo vyměnit, přidat porci nebo jak pokračovat další den."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9112e206-4dbe-4276-b89c-7b6bbb9b939d','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',3,'{"text":"Jak dodržovat jídelníček dlouhodobě? Ne tím, že ho budeš plnit bez jediné odchylky. Tím, že se ho naučíš přizpůsobovat a po každém výpadku se rychle vrátit."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5bddefc4-d5fb-4840-ac65-f8173d0c91a3','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',4,'{"level":"h2","text":"Proč jídelníček selhává až v praxi","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d7649147-4c22-403e-938a-e36b748683cc','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',5,'{"text":"Žádný plán nemůže předvídat každý tvůj den. Může ti dát porce, recepty a základní strukturu. Otázky ale často vzniknou teprve při používání."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('095f95b6-e5c5-4631-b4b7-02d7559a4302','f315a8c1-ead9-42d4-9e2f-de142df5805d','bullet_list',6,'{"items":["Co mám udělat, když nestihnu plánovanou svačinu?","Můžu si vyměnit oběd a večeři?","Co si vybrat v restauraci?","Jak upravit porci, když mám větší hlad?","Co dělat po porušení jídelníčku?","Mám něco měnit, když se váha týden nehýbe?"]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('0859f589-a406-4262-b92d-f4251c7a7770','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',7,'{"text":"Když na tyto otázky nemáš odpověď, začneš improvizovat. A pokud si nejsi jistá, může každá změna vyvolat pocit, že už plán nedodržuješ správně."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5df10016-dc48-465c-b333-a9696b7ab822','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',8,'{"level":"h2","text":"Dodržovat neznamená kopírovat každý řádek","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('1517599d-bbaa-4dc8-82c9-3bbc36259983','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',9,'{"text":"Jídelníček by měl být mapa, ne test poslušnosti. Smyslem není jíst v úterý přesně to, co je napsané v úterý. Smyslem je držet se vhodné skladby a porcí, přestože konkrétní jídla měníš podle situace. Pokud potřebuješ konkrétní příklady jídel, projdi si také [jednoduchý jídelníček na hubnutí](/blog/jednoduchy-jidelnicek-na-hubnuti)."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('9b846246-2ff0-4512-8794-82e55903e5d3','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',10,'{"text":"Čím lépe rozumíš principu, tím méně tě rozhodí chybějící surovina, návštěva nebo změna programu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('5f32e85a-0370-4ba2-9e06-00af15b9fbc8','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',11,'{"level":"h2","text":"Jak vydržet u hubnutí, když týden není ideální","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('af2423a7-7185-406e-bb3b-3578ea91e729','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',12,'{"level":"h3","text":"1. Rozlišuj změnu plánu a opuštění plánu","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('beead285-c156-43f6-8864-d8d4329216d9','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',13,'{"text":"Když si dáš jiný oběd, neznamená to, že jsi jídelníček porušila. Změnila jsi konkrétní jídlo. Pokud dokážeš vybrat podobně složenou variantu, stále pokračuješ."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4955fbf0-a60b-4bd7-a054-a6cd3415b196','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',14,'{"level":"h3","text":"2. Nečekej na další pondělí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('34ebeea4-00f5-4c3d-a2f3-b9326e11dd76','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',15,'{"text":"Jak se vrátit k jídelníčku po horším dni? Dalším normálním jídlem. Ne hladověním, vynecháním snídaně ani trestným cvičením. Čím více návrat odkládáš, tím větší význam jednomu dni dáváš."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('7d9cb30a-ba64-49de-8087-d1cefbfc281c','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',16,'{"level":"h3","text":"3. Řeš opakující se problém, ne jednorázovou situaci","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b66c6df9-d1ff-4151-af02-b3d6d70825d5','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',17,'{"text":"Jedna večeře venku není potřeba opravovat. Pokud ale každý čtvrtek nestíháš oběd a večer se přejíš, má smysl připravit konkrétní čtvrteční řešení."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('b0a3d434-bb35-49b0-84a8-c0cd36fb3a9d','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',18,'{"level":"h3","text":"4. Ptej se, co ti plán komplikuje","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('fe782ab1-a46e-4477-9f7c-91cf39af196b','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',19,'{"text":"Možná je problém v příliš složitých receptech, malé snídani, chybějícím nákupu nebo v tom, že se snažíš vařit zvlášť pro sebe. Odpověď nemusí být menší porce. Často je to jednodušší systém."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('165b75b8-405c-43ce-99c3-b4b62765f28f','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',20,'{"level":"h3","text":"5. Vyhodnocuj celý týden","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('694f4f86-3158-4cf1-b4cb-e581ffeb8600','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',21,'{"text":"Týdenní pohled ukáže, co funguje opakovaně a kde se stále zasekáváš. Jednotlivý den může být náhoda. Vzorec už je užitečná informace."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('64bb5c84-d7ca-478a-ad8d-b839d94470e9','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',22,'{"level":"h2","text":"Kdy už obecné rady nestačí","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6798255d-0651-4794-8a21-4b9e96465ab7','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',23,'{"text":"Na internetu najdeš odpověď na téměř každou otázku. Problém je, že nezná tvůj jídelníček, příjem ani průběh týdne. Jedna rada doporučí ubrat, druhá přidat, třetí úplně změnit směr."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('762a9b68-9711-4303-90b3-64cd60ef2aff','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',24,'{"text":"Online podpora při hubnutí má hodnotu právě v návaznosti. Člověk, který zná tvůj plán a předchozí týden, dokáže posoudit otázku v kontextu. Nemusíš pokaždé vysvětlovat všechno od začátku ani skládat radu z deseti různých zdrojů."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('cde45c0a-df77-4e0d-92b5-ac0313c322ae','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',25,'{"level":"h2","text":"Proč funguje týdenní zpětná vazba","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('2eb590d5-f607-42af-8f22-e63f0943fb11','f315a8c1-ead9-42d4-9e2f-de142df5805d','bullet_list',26,'{"items":["Zastavíš se a pojmenuješ, co se ti skutečně podařilo.","Odhalíš problém dříve, než kvůli němu celý plán opustíš.","Dostaneš konkrétní úpravu na další týden.","Nevyhodnocuješ vše jen podle momentálního pocitu nebo váhy.","Víš, že se máš kde zeptat, když si nejsi jistá."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('42ec20af-0764-4d70-aa67-6343a1e4a122','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',27,'{"level":"h2","text":"Jak vypadá 4týdenní e-mailová podpora","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('3ca60d03-2de2-4778-b657-f9f33f52ab6f','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',28,'{"text":"Během čtyř týdnů pravidelně shrneš svůj týden. Popíšeš, co se dařilo, kde vznikl hlad, co jsi nestihla nebo s čím sis nevěděla rady. Dostaneš zpětnou vazbu a konkrétní doporučení pro další postup."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('365ff5d1-1bf7-49bf-bde7-235f0a69bebd','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',29,'{"text":"Součástí je také WhatsAppová skupina. Když se otázka objeví během běžného dne, nemusíš ji odkládat nebo hledat náhodnou odpověď. Můžeš se zeptat kdykoliv na konkrétní situaci."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('4edf853a-815a-4716-8212-47974ff92909','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',30,'{"level":"h2","text":"Podpora není kontrola ani hodnocení","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('86104fad-1990-401f-b16f-32e25931e698','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',31,'{"text":"Nebudeš dostávat známku za to, jak přesně jsi plán splnila. Smyslem je najít způsob, který bude fungovat v tvém životě. Někdy to znamená upravit porce. Jindy zjednodušit recepty, přesunout jídla nebo připravit nouzovou variantu."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('220b332f-fb65-49c3-885e-0b2ec37b1f43','f315a8c1-ead9-42d4-9e2f-de142df5805d','paragraph',32,'{"text":"Čtyři týdny jsou dost dlouhé na to, aby se objevily různé situace, a zároveň dost konkrétní na to, aby ses soustředila na postupné zavedení plánu do praxe."}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('d8932dee-bf83-44f2-a6d1-5561c2054d39','f315a8c1-ead9-42d4-9e2f-de142df5805d','heading',33,'{"level":"h2","text":"Pro koho je podpora vhodná","anchor":""}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('6d09e4e4-6484-4026-b1c1-39a5df6b7749','f315a8c1-ead9-42d4-9e2f-de142df5805d','bullet_list',34,'{"items":["Máš jídelníček nebo základní plán, ale nevíš, jak ho přizpůsobovat.","Po každé odchylce máš pocit, že musíš začít znovu.","Potřebuješ možnost zeptat se na konkrétní situaci.","Chceš pravidelnou zpětnou vazbu, ne další obecné materiály.","Víš, co dělat, ale potřebuješ pomoc s převedením do běžného týdne."]}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_blocks (id,article_id,block_type,position,content,settings) values ('368edde8-0743-4da4-b8c0-0a37e5979b8b','f315a8c1-ead9-42d4-9e2f-de142df5805d','cta',35,'{"eyebrow":"4týdenní podpora","title":"Nechceš všechny otázky při změně řešit sama?","text":"Během čtyř týdnů získáš pravidelnou zpětnou vazbu, jasnou prioritu pro další týden a možnost průběžně řešit konkrétní situace.","button_label":"Zjistit více o 4týdenní podpoře","url":"/nabidka-podpory/emailova-konzultace","new_window":false}'::jsonb,'{}'::jsonb);
  insert into public.blog_article_relations (id,article_id,related_article_id,position) values ('b4afe039-03c5-44a0-b0b8-8911d9c3bf03','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','53feef80-04f3-4d91-a323-4c24a06c22de',1);
  insert into public.blog_article_relations (id,article_id,related_article_id,position) values ('2bb38ae3-4d5a-422a-a164-724171124120','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','1bf1840f-bab2-4d0d-8a9f-f35b413b03c3',2);
