  insert into public.blog_article_relations (id,article_id,related_article_id,position) values ('c5fb1647-0793-4cbb-8aee-dda6adc4805b','7d4dc0ef-aee6-49c6-961e-ae10ed901169','7643e411-f8b9-4035-9cbb-9a8ad2e5cab8',1);
  insert into public.blog_article_relations (id,article_id,related_article_id,position) values ('465f5cbd-213b-460c-b5ed-77d3aeb88a51','7d4dc0ef-aee6-49c6-961e-ae10ed901169','53feef80-04f3-4d91-a323-4c24a06c22de',2);
