  select count(*) into found_count from public.blog_articles where title in ('21denní výzva pro začátečnice: jak začít cvičit bez přepálení', 'Jak začít hubnout, když nemáš čas: první 3 týdny bez dokonalého plánu', 'Jídelníček na hubnutí pro zaneprázdněné ženy: co musí fungovat v praxi', 'Večerní hlad při hubnutí: proč vzniká už během dne a jak mu předejít', 'Jak se motivovat k hubnutí a vydržet, i když první nadšení zmizí', 'Komunita Fit bez času: podpora pro zdravější režim bez tlaku', 'Aplikace Fit bez času nebo Plus: kterou variantu zvolit', 'Aplikace na počítání kalorií: jak ji používat bez dalšího stresu', 'Osobní rozbor jídelníčku: co může odhalit a jak probíhá', 'Proč nehubnu, i když se snažím? 7 možných důvodů', '4týdenní podpora při hubnutí: jak funguje v běžném životě', 'Jak dodržovat jídelníček v běžném životě a nevzdat ho po prvním týdnu') or seo_title in ('21denní výzva pro začátečnice', 'Jak začít hubnout, když nemáš čas', 'Jídelníček na hubnutí pro zaneprázdněné ženy', 'Večerní hlad při hubnutí: příčiny a řešení', 'Jak se motivovat k hubnutí a vydržet', 'Komunita Fit bez času: jak funguje', 'Aplikace Fit bez času nebo Plus', 'Aplikace na počítání kalorií bez stresu', 'Osobní rozbor jídelníčku: jak probíhá', 'Proč nehubnu, i když se snažím? 7 důvodů', '4týdenní podpora při hubnutí: jak funguje', 'Jak dodržovat jídelníček') or seo_description in ('Zjisti, jak probíhá 21denní výzva pro začátečnice, proč staví na krátkém domácím cvičení a komu pomůže vytvořit udržitelný pohybový návyk.', 'Nevíš, jak začít hubnout vedle práce a rodiny? Nastav si krátký pohyb, minimální variantu a první tři týdny tak, aby se daly opravdu zvládnout.', 'Zjisti, jak má fungovat jídelníček na hubnutí pro zaneprázdněné ženy: porce, rychlá jídla, obměny i společné vaření bez druhého hrnce.', 'Večerní hlad často začíná malými porcemi a nepravidelným jídlem přes den. Zjisti, jak poskládat sytější jídla a předejít večerním chutím.', 'Motivace k hubnutí kolísá. Nauč se používat menší kroky, sledovat pokrok i mimo váhu a vytvořit si podporu, která funguje ve slabších dnech.', 'Zjisti, co nabízí Komunita Fit bez času: krátká cvičení, jednoduché recepty, pravidelnou inspiraci a podporu pro ženy s plným diářem.', 'Porovnej Aplikaci Fit bez času a variantu Plus. Zjisti, kdy stačí zapisování jídla a kdy se hodí jídelníček, konkrétní porce a vzorové dny.', 'Jak používat aplikaci na počítání kalorií bez posedlosti čísly? Nauč se zapisovat poctivě, číst souvislosti a vyhodnocovat více běžných dní.', 'Zjisti, co může osobní rozbor jídelníčku odhalit v porcích, skladbě dne a pravidelnosti a jak získáš konkrétní priority místo dalších zákazů.', 'Snažíš se, ale váha se nehýbe? Projdi sedm častých důvodů od malého jídla přes víkendy až po nepřesný odhad a zjisti, co řešit jako první.', 'Zjisti, jak funguje 4týdenní podpora při hubnutí, týdenní zpětná vazba a průběžné otázky přes WhatsApp, když potřebuješ plán převést do praxe.', 'Zjisti, jak dodržovat jídelníček bez perfekcionismu: měnit jídla, vrátit se po horším dni, řešit opakované překážky a vyhodnotit celý týden.');
