  values ('7643e411-f8b9-4035-9cbb-9a8ad2e5cab8','21denní výzva pro začátečnice: jak začít cvičit bez přepálení','21denni-vyzva-pro-zacatecnice','Krátké domácí cvičení, jasný plán a prostor pro horší dny. Podívej se, jak 21denní výzva pomáhá začátečnicím vytvořit zvládnutelný pohybový návyk.','6fbec80c-0667-48a7-897e-3878c9d072f8','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'21denní výzva pro začátečnice','Zjisti, jak probíhá 21denní výzva pro začátečnice, proč staví na krátkém domácím cvičení a komu pomůže vytvořit udržitelný pohybový návyk.',null,null,true,false,true,null,null,null);
  values ('7d4dc0ef-aee6-49c6-961e-ae10ed901169','Jak začít hubnout, když nemáš čas: první 3 týdny bez dokonalého plánu','jak-zacit-hubnout-kdyz-nemas-cas','Začátek hubnutí nemusí znamenat kompletní změnu režimu. Zjisti, jak nastavit první tři týdny, krátký pohyb a minimální variantu pro náročné dny.','6fbec80c-0667-48a7-897e-3878c9d072f8','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Jak začít hubnout, když nemáš čas','Nevíš, jak začít hubnout vedle práce a rodiny? Nastav si krátký pohyb, minimální variantu a první tři týdny tak, aby se daly opravdu zvládnout.',null,null,true,false,true,null,null,null);
  values ('ca0d4cb8-a786-4d93-9d49-b730345c5c37','Jídelníček na hubnutí pro zaneprázdněné ženy: co musí fungovat v praxi','jidelnicek-na-hubnuti-pro-zaneprazdnene','Funkční jídelníček musí počítat s prací, rodinou i dny bez času na vaření. Projdi si porce, rozložení jídel, rychlé varianty a praktické obměny.','2d2519ad-ad9e-40da-9f62-f449938757c2','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Jídelníček na hubnutí pro zaneprázdněné ženy','Zjisti, jak má fungovat jídelníček na hubnutí pro zaneprázdněné ženy: porce, rychlá jídla, obměny i společné vaření bez druhého hrnce.',null,null,true,false,true,null,null,null);
  values ('67cceed5-a712-4d31-a19e-d0745931cfca','Večerní hlad při hubnutí: proč vzniká už během dne a jak mu předejít','vecerni-hlad-pri-hubnuti','Večerní hlad často nezačíná večer. Podívej se, jak ho ovlivňují malé porce, nepravidelnost, bílkoviny a skladba hlavních jídel během dne.','2d2519ad-ad9e-40da-9f62-f449938757c2','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Večerní hlad při hubnutí: příčiny a řešení','Večerní hlad často začíná malými porcemi a nepravidelným jídlem přes den. Zjisti, jak poskládat sytější jídla a předejít večerním chutím.',null,null,true,false,true,null,null,null);
  values ('36b8aa9c-b544-466d-b5ba-eb0648a1cf0a','Jak se motivovat k hubnutí a vydržet, i když první nadšení zmizí','jak-se-motivovat-k-hubnuti','Motivace není stabilní. Nauč se pokračovat pomocí menších kroků, základního plánu, širšího pohledu na pokrok a prostředí, které tě podrží ve slabších dnech.','8e5162e3-28f0-4313-be2f-050bc53de3fa','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Jak se motivovat k hubnutí a vydržet','Motivace k hubnutí kolísá. Nauč se používat menší kroky, sledovat pokrok i mimo váhu a vytvořit si podporu, která funguje ve slabších dnech.',null,null,true,false,true,null,null,null);
  values ('c9609bb3-5bad-4c25-9551-9f42668bc778','Komunita Fit bez času: podpora pro zdravější režim bez tlaku','komunita-fit-bez-casu-jak-funguje','Podívej se, jak Komunita Fit bez času spojuje krátké domácí cvičení, jednoduché recepty a pravidelnou podporu, ze které si vybíráš podle svého týdne.','8e5162e3-28f0-4313-be2f-050bc53de3fa','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Komunita Fit bez času: jak funguje','Zjisti, co nabízí Komunita Fit bez času: krátká cvičení, jednoduché recepty, pravidelnou inspiraci a podporu pro ženy s plným diářem.',null,null,true,false,true,null,null,null);
  values ('a944e07f-99ec-4fdd-acb6-6c7da9dfdc05','Aplikace Fit bez času nebo Plus: kterou variantu zvolit','aplikace-fit-bez-casu-nebo-plus','Aplikace ti dá přehled o příjmu a živinách, Plus přidává konkrétní jídelníček, porce a vzorové dny. Porovnej obě varianty podle toho, co právě potřebuješ.','2d2519ad-ad9e-40da-9f62-f449938757c2','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Aplikace Fit bez času nebo Plus','Porovnej Aplikaci Fit bez času a variantu Plus. Zjisti, kdy stačí zapisování jídla a kdy se hodí jídelníček, konkrétní porce a vzorové dny.',null,null,true,false,true,null,null,null);
  values ('1c1bf782-e6d5-464e-9c5f-f9fa20936a1b','Aplikace na počítání kalorií: jak ji používat bez dalšího stresu','aplikace-na-pocitani-kalorii','Počítání kalorií má přinést informace, ne další známku za úspěch nebo selhání. Nauč se zapisovat běžné dny, sledovat souvislosti a vyhodnocovat vzorce.','2d2519ad-ad9e-40da-9f62-f449938757c2','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Aplikace na počítání kalorií bez stresu','Jak používat aplikaci na počítání kalorií bez posedlosti čísly? Nauč se zapisovat poctivě, číst souvislosti a vyhodnocovat více běžných dní.',null,null,true,false,true,null,null,null);
  values ('9d363cb7-74e8-489a-9b38-2c7bdc428de4','Osobní rozbor jídelníčku: co může odhalit a jak probíhá','osobni-rozbor-jidelnicku-jak-probiha','Osobní rozbor nehledá jednu zakázanou potravinu. Sleduje porce, skladbu dne, pravidelnost a situace, které se opakují, aby určil několik konkrétních priorit.','2d2519ad-ad9e-40da-9f62-f449938757c2','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Osobní rozbor jídelníčku: jak probíhá','Zjisti, co může osobní rozbor jídelníčku odhalit v porcích, skladbě dne a pravidelnosti a jak získáš konkrétní priority místo dalších zákazů.',null,null,true,false,true,null,null,null);
  values ('99b3c520-57b1-4dba-a726-2d7ab97a3fc8','Proč nehubnu, i když se snažím? 7 možných důvodů','proc-nehubnu-i-kdyz-se-snazim','Otázka proč nehubnu nemá jednu univerzální odpověď. Projdi sedm častých důvodů a zjisti, proč je potřeba hodnotit celý den, týden i použitelnost plánu.','2d2519ad-ad9e-40da-9f62-f449938757c2','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Proč nehubnu, i když se snažím? 7 důvodů','Snažíš se, ale váha se nehýbe? Projdi sedm častých důvodů od malého jídla přes víkendy až po nepřesný odhad a zjisti, co řešit jako první.',null,null,true,false,true,null,null,null);
  values ('bf8cb301-196c-4833-9b47-04e765c50ee5','4týdenní podpora při hubnutí: jak funguje v běžném životě','4tydenni-podpora-pri-hubnuti-jak-funguje','Jídelníček nemůže předvídat každý den. Podívej se, jak 4týdenní podpora využívá týdenní zpětnou vazbu a průběžné otázky při převádění plánu do praxe.','8e5162e3-28f0-4313-be2f-050bc53de3fa','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'4týdenní podpora při hubnutí: jak funguje','Zjisti, jak funguje 4týdenní podpora při hubnutí, týdenní zpětná vazba a průběžné otázky přes WhatsApp, když potřebuješ plán převést do praxe.',null,null,true,false,true,null,null,null);
  values ('f315a8c1-ead9-42d4-9e2f-de142df5805d','Jak dodržovat jídelníček v běžném životě a nevzdat ho po prvním týdnu','jak-dodrzovat-jidelnicek','Dodržovat jídelníček neznamená přesně kopírovat každý řádek. Nauč se měnit jídla, vrátit se po horším dni a řešit překážky, které se opakují.','8e5162e3-28f0-4313-be2f-050bc53de3fa','5c9fe7fb-ca71-40c4-ae87-5aaf9e3c6260','draft',null,null,null,'Jak dodržovat jídelníček','Zjisti, jak dodržovat jídelníček bez perfekcionismu: měnit jídla, vrátit se po horším dni, řešit opakované překážky a vyhodnotit celý týden.',null,null,true,false,true,null,null,null);
